window.JASTROW_CHUNKS[1016]={"38912":{"h":"יָאִי","r":"KRU08374","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  חול׳ ו׳ ע״א: איקלעו לפונדקא דיאי. </p>","notation":["שם מקום"]},"38913":{"h":"יָאֵי","r":"KRU08375","alt":["יָאיָא"],"source":"krupnik","glosses":[{"text":"right, nice","label":""}],"html":"<p>יפה, טוב right, nice  מנ׳ נ״ג ע״א: אי בר אורין הוא יאי ואי בר אורין ובר אבהן יאי ויאי; תרג׳ יב״ע בר׳ כ״ט י״ז (יפת מראה): יאיא בריווא.</p>","notation":[]},"38914":{"h":"יָאֲיָא","r":"KRU08376","alt":[],"source":"krupnik","glosses":[{"text":"beauty","label":""}],"html":"<p>יופי beauty  תרג׳ איוב ח׳ ו׳ (נות צדקך): יאית צדקך.</p>","notation":["נ׳"]},"38915":{"h":"יֵאנָא","r":"KRU08381","alt":[],"source":"krupnik","glosses":[{"text":"I will","label":""}],"html":"<p>אהיה, אעשה I will  ירוש׳ קיד׳ פ״ד ס״ו ע״ב: את חמי מפייס יאנא מוקים ליה.</p>","notation":["Equivalent spelling: יֵא נָא · יְהֵא אֲנָא"]},"38916":{"h":"יָאנִיבָא","r":"KRU08382","alt":[],"source":"krupnik","glosses":[{"text":"moth","label":""}],"html":"<p>עש moth  חול׳ פ״ה ע״ב: נפל ליה יאניבא בכיתניה.</p>","notation":["ז׳"]},"38917":{"h":"יָאסִין","r":"KRU08383","alt":["יאסיניאה"],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  תוס׳ מנח׳ א׳ ט״ו: ר׳ יוסי בר יאסין: ביצה ח׳ ע״ב: א״ר יוסי בר יאסיניאה. </p>","notation":[]},"38918":{"h":"יָארוֹד","r":"KRU08384","alt":[],"source":"krupnik","glosses":[{"text":"leucoma","label":""}],"html":"<p>כתם לבן בעין leucoma  שבת ע״ח ע״א: דם כדי לכחול בו עין אחת שכן כוחלין ליארוד.</p>","notation":["ז׳"]},"38919":{"h":"יאש","r":"KRU08385","alt":[],"source":"krupnik","glosses":[{"text":"to give up, to despair, to discard from the mind","label":"חִתְיָאֵשׁ התפ׳,"}],"html":"<p>חִתְיָאֵשׁ התפ׳, נואש, אבדה תקותו to give up, to despair, to discard from the mind  סעו״ר כ״ח: כל שהוא בטובה אל יתיאש מן הרעה וכל שהוא ברעה אל יתיאש מן הטובה.</p>","notation":["Source marks no qal form"]},"38920":{"h":"יֵבָא","r":"KRU08390","alt":[],"source":"krupnik","glosses":[{"text":"it corresponds to","label":""}],"html":"<p>הרי זה, הדבר דומה it corresponds to  ירוש׳ שבת פ״ג ו׳ ע״ד: יבא כיי דמר ר׳ זעירא.</p>","notation":["מה״י"]},"38921":{"h":"יבֵּב","r":"KRU08391","alt":[],"source":"krupnik","glosses":[{"text":"to lament","label":""}],"html":"<p>הספיד to lament  ירוש׳ יבמ׳ פט״ז ט״ו ע״ד: שמע קול המקוננת מיבבתו בין המתים.</p>","notation":["Marked biblical in source"]},"38922":{"h":"יַבֵּב","r":"KRU08392","alt":[],"source":"krupnik","glosses":[{"text":"to sound an alarm","label":""},{"text":"to shout","label":""}],"html":"<p>תקע והריע to sound an alarm  תרג׳ במ׳ י, ט׳ (והרעותם בחצוצרות): ותיבבון בחצוצרתא. אִתְיַבֵּב אתפ׳, צהל to shout  תרג׳ תה׳ ק״ח י׳ (עלי פלשת אתרועע): על מלכות פלישתאי אתיבב. </p>","notation":["פַעל"]},"38923":{"h":"יַבָּבָא","r":"KRU08393","alt":[],"source":"krupnik","glosses":[{"text":"alarm","label":""}],"html":"<p>תרועה alarm  תרג׳ במ׳ כ״ט א׳ (יום תרועה): יום יבבא.</p>","notation":["נ׳"]},"38924":{"h":"יְבָבָה","r":"KRU08394","alt":[],"source":"krupnik","glosses":[{"text":"trembling note, staccato","label":""}],"html":"<p>קול מקוטע של תקיעה trembling note, staccato  ר״ה פ״ד מ״ט: שיעור תקיעות כשלש תרועות שיעור תרועה כשלש יבבות.</p>","notation":["נ׳"]},"38925":{"h":"יְבַד","r":"KRU08396","alt":[],"source":"krupnik","glosses":[{"text":"to get lost, to perish","label":""}],"html":"<p>הלך לאיבוד to get lost, to perish  ירוש׳ שבי׳ פ״ט ל״ח ע״ד: צפור מבלעדי שמיא לא יבדא כל שכן בר נשא.</p>","notation":["פ״ע"]},"38926":{"h":"יַבּוֹלֶת","r":"KRU08399","alt":[],"source":"krupnik","glosses":[{"text":"wart","label":"1"},{"text":"parasitic excrescence on tree","label":"2"}],"html":"<p>1 ספחת בעור הגוף, יבלת wart  ירוש׳ פסח׳ פ״ו ל״ג: יבולת ראויה ליחתך מאתמול.\n2 ספחת בצמח parasitic excrescence on tree  ירוש׳ שבי׳ פ״ב ל״ג ע״ד: מעבירין את היבולת מפרקין בעלין.</p>","notation":["נ׳"]},"38927":{"h":"יִבּוּם","r":"KRU08400","alt":[],"source":"krupnik","glosses":[{"text":"levirate marriage","label":""}],"html":"<p>חובת נשיאת אשת האח המת levirate marriage  יבמ׳ פ״א: מן החליצה ומן היבום.</p>","notation":["ז׳"]},"38928":{"h":"יַבְחוּשׁ","r":"KRU08401","alt":[],"source":"krupnik","glosses":[{"text":"a sort of gnat","label":""}],"html":"<p>מין שרץ קטן a sort of gnat  חול׳ ס״ז ע״א: כל השרץ השורץ על הארץ לרבות יבחושין שסיננן.</p>","notation":["ז׳"]},"38929":{"h":"יַבִּישׁ","r":"KRU08404","alt":[],"source":"krupnik","glosses":[{"text":"dry","label":""}],"html":"<p>יבש dry  תרג׳ איוב י״ג כ״ה (קש יבש): גילא יביש.</p>","notation":["ת׳"]},"38930":{"h":"יַבִּישְׁתָּא","r":"KRU08405","alt":[],"source":"krupnik","glosses":[{"text":"continent","label":""}],"html":"<p>יבשה continent  תרג׳ תה׳ צ״ה ה׳ (ויבשת): ויבישתא.</p>","notation":["נ׳"]},"38931":{"h":"יבל","r":"KRU08407","alt":[],"source":"krupnik","glosses":[{"text":"to cut off dry twigs","label":"יִבֵּל פיעל,"}],"html":"<p>יִבֵּל פיעל, חתך את היבלת מן הצמח to cut off dry twigs  שבי׳ פ״ב מ״ב: מיבלין מפרקין מעשנין עד ר״ה.</p>","notation":["Source marks no qal form"]},"38932":{"h":"יבל²","r":"KRU08408","alt":[],"source":"krupnik","glosses":[{"text":"to carry, to bring","label":"אוֹבִיל, אֵיבִיל אפ׳,"}],"html":"<p>אוֹבִיל, אֵיבִיל אפ׳, הביא, נשא to carry, to bring  עיר׳ כ״ז ע״ב: מאן דמתרגם לי וכו׳ מובילנא מאניה אבתריה לבי מסותא; ירוש׳ תענ׳ פ״ג ס״ו ע״ד: מה עיסקא דהדא אבן הטועים וכו׳ וכל דהוה משכח מילא הוה מייביל לה לתמן.\nאִתּוֹבַל אתפ׳, הובא to be brought, carried | geführt, gebracht werden תרג׳ יש׳ ל״ט ו׳ (ונשא וגו׳ בבל): ויתובל לבבל.</p>","notation":["Source marks no qal form"]},"38933":{"h":"יִבְלָא","r":"KRU08409","alt":[],"source":"krupnik","glosses":[{"text":"brook","label":""}],"html":"<p>פלג, יובל brook  תרג׳ איכה ג׳ מ״ח (פלגי מים): יבלין דמיא.</p>","notation":["ז׳"]},"38934":{"h":"יַבְלָא","r":"KRU08410","alt":[],"source":"krupnik","glosses":[{"text":"Cynodon","label":""}],"html":"<p>מין עשב Cynodon  חול׳ ק״ה ע״ב: עקרינהו ליבלי.</p>","notation":["ז׳"]},"38935":{"h":"יַבְלִית","r":"KRU08412","alt":[],"source":"krupnik","glosses":[{"text":"a pulp made of Cynodon leaves","label":""}],"html":"<p>דבק הנעשה מעלי יבלא a pulp made of Cynodon leaves  כל׳ פ״ג מ״ו: יבלית שטופלין בה את הפטסים.</p>","notation":["נ׳"]},"38936":{"h":"יַבְּלָן","r":"KRU08413","alt":[],"source":"krupnik","glosses":[{"text":"one afflicted with warts","label":""}],"html":"<p>בעל יבלות one afflicted with warts  תרג׳ ויק׳ כ״ב כ״ב (יבלת): יבלן.</p>","notation":["ז׳"]},"38937":{"h":"יָבָם","r":"KRU08415","alt":[],"source":"krupnik","glosses":[{"text":"husband’s brother, who in the case of his brother dying without issue marries his wife","label":""}],"html":"<p>אחי המת בלי בנים המחוייב לשאת את האלמנה לאשה husband’s brother, who in the case of his brother dying without issue marries his wife  יבמ׳ פ״ג מ״ט: זיקת יבם אחד ולא זיקת שני יבמין.</p>","notation":["Marked biblical in source"]},"38938":{"h":"יִבֵּם","r":"KRU08416","alt":[],"source":"krupnik","glosses":[{"text":"to be married by the yabam","label":"הִתְיַבֵּם התפ׳,"}],"html":"<p>הִתְיַבֵּם התפ׳, נישאה ליבם to be married by the yabam  תוס׳ יבמ׳ י״ד א׳: ונתיבמתי ליבמי.</p>","notation":["Marked biblical in source"]},"38939":{"h":"יַבֵּם","r":"KRU08417","alt":[],"source":"krupnik","glosses":[{"text":"to marry the wife of a brother who died without issue","label":""}],"html":"<p>קיים מצות יבום, נשא את אלמנת אחיו שמת בלי בנים to marry the wife of a brother who died without issue  יבמ׳ ל״ט ע״ב: אי בעית חלוץ אי בעית ייבם. אִתְיַבֵּם, אִיַּבֵּם אתפ׳, עי׳ נִתְיַבֵּם (יִבֵּם). יבמ׳ ל״ב ע״א: תתייבם יבומי; שם ל׳ ע״א: לייבומי. </p>","notation":["פעל"]},"38940":{"h":"יְבָמָה","r":"KRU08418","alt":[],"source":"krupnik","glosses":[{"text":"the widow of a brother who died without issue","label":""}],"html":"<p>·–אלמנת האח שמת בלי בנים the widow of a brother who died without issue  יבמ׳ פ״ד מ״י: היבמה לא תחלוץ ולא תתיבם עד שיהיו לה שלשה חדשים.</p>","notation":[]},"38941":{"h":"יְבָמוּת","r":"KRU08419","alt":[],"source":"krupnik","glosses":[{"text":"the marriage of the yabam","label":""}],"html":"<p>נשואי יבום the marriage of the yabam  יבמ׳ נ״ב ע״ב: קידשה לשם יבמות.</p>","notation":["נ׳"]},"38942":{"h":"יְבַמְתָּא","r":"KRU08422","alt":[],"source":"krupnik","glosses":[{"text":"sister-in-law","label":""}],"html":"<p>גיסה sister-in-law  תרג׳ רות א׳ ט״ו (יבמתך): יבמתיך.</p>","notation":["נ׳"]},"38943":{"h":"יַבְּקָא","r":"KRU08424","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ירוש׳ שבי׳ פ״ו ל״ג: חשבון ויבקא. </p>","notation":["שם מקום"]},"38944":{"h":"יַבְרוּחַ","r":"KRU08425","alt":["יַבְרוּחָא","יַבְרוּחָה"],"source":"krupnik","glosses":[{"text":"mandragora","label":""}],"html":"<p>שורש דודאים mandragora  ב״ר פע״ב: דודאים וכו׳ יברוחין; תרג׳ בר׳ ל׳ ט״ו (דודאי בני): יברוחי דברי; ירוש׳ עיר׳ פ״י כ״ו ע״ג: וההן דקרי על יברוחה וכו׳.</p>","notation":[]},"38945":{"h":"יְבֵשׁ","r":"KRU08426","alt":[],"source":"krupnik","glosses":[{"text":"to be dry, to dry up","label":""}],"html":"<p>היה יבש, נתיבש to be dry, to dry up  תרג׳ תה׳ ק״ב י״ב (כעשב איבש): היך עיסבא איבש.</p>","notation":["פ״ע"]},"38946":{"h":"יַבֵּשׁ","r":"KRU08427","alt":[],"source":"krupnik","glosses":[{"text":"to dry","label":""},{"text":"to be dried up","label":""}],"html":"<p>עשה יבש to dry  תרג׳ מש׳ י״ז כ״ב (תיבש עצם): מיבשא גרמא. אִתְיַבֵּשׁ אתפ׳, נעשה יבש to be dried up  תרג׳ תה׳ צ׳ ו׳ (ימולל ויבש): ומתיבש מן חורבא. </p>","notation":["פַעל"]},"38947":{"h":"יַבֶּשֶׁת","r":"KRU08428","alt":[],"source":"krupnik","glosses":[{"text":"dry fruits","label":""}],"html":"<p>פירות מיובשים dry fruits  תוס׳ שבי׳ ד׳ ט״ז: אין כובשין ואין מייבשין יבשת.</p>","notation":["Marked biblical in source"]},"38948":{"h":"יגא","r":"KRU08430","alt":[],"source":"krupnik","glosses":[{"text":"toga, Roman gown","label":""}],"html":"<p>מלבוש רומי toga, Roman gown  ספרי דב׳ רל״ד: פרט ליגא.</p>","notation":["נ׳","Source emendation: טוֹגָא"]},"38949":{"h":"יְגוּדְיוֹ","r":"KRU08433","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  תוס׳ צוק׳ אהל׳ י״ח ט״ו: תחומי אשקלין מקבר גדול ועד יגודיו. </p>","notation":["שם מקום"]},"38950":{"h":"יְגוֹר","r":"KRU08434","alt":[],"source":"krupnik","glosses":[{"text":"heap","label":""}],"html":"<p>גל heap  תרג׳ איוב ט״ו כ״ח (אשר התעתדו לגלים): די אתעתדו ליגורין.</p>","notation":["ז׳"]},"38951":{"h":"יָגֵעַ","r":"KRU08435","alt":[],"source":"krupnik","glosses":[{"text":"to be tired","label":"הִתְיַגֵּעַ התפ׳,"}],"html":"<p>הִתְיַגֵּעַ התפ׳, נעשה עיף to be tired  פסדר״כ שובה: מעט בריצה שלא תתייגע בחזירה.</p>","notation":["Marked biblical in source"]},"38952":{"h":"יַגְרִי","r":"KRU08436","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  תוס׳ שבי׳ ד׳ ח׳: עיירות המותרות בתחום נואי וכו׳ וזיזין ויגרי. </p>","notation":["שם מקום"]},"38953":{"h":"יָד","r":"KRU08438","alt":[],"source":"krupnik","glosses":[{"text":"forefoot","label":""}],"html":"<p>רגל הקדמית בבע״ח forefoot  חול׳ נ״ח ע״ב: לא שנו אלא שחסר ויתר ביד אבל חסר ויתר ברגל.</p>","notation":["Marked biblical in source"]},"38954":{"h":"יַד … בָּאֶמְצַע","r":"KRU08439","alt":[],"source":"krupnik","glosses":[{"text":"he has a share in it","label":""}],"html":"<p>יש לו חלק בדבר he has a share in it  ב״מ ע׳ ע״ב: יד הנכרי באמצע.</p>","notation":[]},"38955":{"h":"יַד … עַל הָעֶלְיוֹנָה","r":"KRU08440","alt":[],"source":"krupnik","glosses":[{"text":"he is at an advantage","label":""}],"html":"<p>זכותו מרובה משל חבירו he is at an advantage  ב״מ ע״ז ע״ב: יד לוקח על העליונה.</p>","notation":[]},"38956":{"h":"יָד רְחָבָה","r":"KRU08441","alt":[],"source":"krupnik","glosses":[{"text":"liberality","label":""}],"html":"<p>נדבנות liberality  ירוש׳ חג׳ פ״א ע״ו ע״ג: עני וידו רחבה.</p>","notation":[]},"38957":{"h":"יָדוֹ עַל הַתַּחְתּוֹנָה","r":"KRU08442","alt":[],"source":"krupnik","glosses":[{"text":"his rights are the lowest, is at a disadvantage","label":""}],"html":"<p>זכותו ירודה משל חבירו his rights are the lowest, is at a disadvantage  ב״מ פ״ו מ״ב: כל המשנה ידו על התחתונה.</p>","notation":[]},"38958":{"h":"יָדָיו יָפוֹת","r":"KRU08443","alt":[],"source":"krupnik","glosses":[{"text":"he is skillful","label":""},{"text":"to","label":""}],"html":"<p>זריז ומהיר הוא he is skillful  פסח׳ פ״ט ע״ב: שהיו ידיו של אחד מהן יפות. לִידֵי לתוך, אל to  אבות פ״ג מ״א: הסתכל בשלשה דברים ואין אתה בא לידי עבירה. </p>","notation":[]},"38959":{"h":"יִדֵּא","r":"KRU08444","alt":[],"source":"krupnik","glosses":[{"text":"to fly","label":"פיעל,"}],"html":"<p>פיעל, עף, פרח to fly  מדר׳ תהל׳ י״ח י״א: והוא מיידא.</p>","notation":[]},"38960":{"h":"יְדָא","r":"KRU08445","alt":[],"source":"krupnik","glosses":[{"text":"hand","label":""},{"text":"through","label":""}],"html":"<p>יד hand  תרג׳ שמ׳ כ״א כ״ד (יד תחת יד): ידא תחת ידא. אַיָּדָא על ידי through  ע״ז ט״ו: אידא דספסירא. </p>","notation":["נ׳"]},"38961":{"h":"יְדַד","r":"KRU08446","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ירוש׳ מו״ק פ״ג פ״ב ע״א: אחד מעמתן ואחד מידד. </p>","notation":["שם מקום"]},"38962":{"h":"יַדּוּעַ","r":"KRU08447","alt":[],"source":"krupnik","glosses":[{"text":"jerboa","label":""}],"html":"<p>מין בעל חי דומה לעכבר jerboa  סנה׳ ס״ה ע״ב: ידעוני זה המניח עצם ידוע בפיו והוא מדבר מאיליו.</p>","notation":["ז׳"]},"38963":{"h":"ידי","r":"KRU08449","alt":[],"source":"krupnik","glosses":[{"text":"to admit, to confess","label":"אוֹדִי, הוֹדִי אפ׳ 1"},{"text":"to thank","label":"אוֹדִי, הוֹדִי אפ׳ 2"}],"html":"<p>אוֹדִי, הוֹדִי אפ׳ 1 הודה על האמת, התודה to admit, to confess  יומא ז׳ ע״א: מודינא; שבוע׳ ל״ט ע״ב: כפר במקצת והודה במקצת.\nאוֹדִי, הוֹדִי אפ׳ 2 הביע את תודתו to thank  בר׳ מ״ה ע״ב: צריך לאודויי; תרג יב״ע דב׳ ח׳ י׳: מודין ומברכין.\nאִתְוַדֵּי אתפ׳, כנ״ל 1. תרג׳ ירוש׳ דב׳ ג׳ כ״ט: מתודין על חטאין. </p>","notation":["Source marks no qal form"]},"38964":{"h":"יְדִיָעה","r":"KRU08450","alt":["יְדִיֲעתָא"],"source":"krupnik","glosses":[{"text":"knowledge, consciousness","label":""}],"html":"<p>דעת והכרה knowledge, consciousness  שבועות פ״א מ״ב: ידיעה בתחלה וידיעה בסוף והעלם בינתיים; תרג׳ מש׳ ל׳ ג׳ (דעת קדושים): ידיעתא דקדישי.</p>","notation":[]},"38965":{"h":"יָדַע בְּיָדוּעַ","r":"KRU08451","alt":[],"source":"krupnik","glosses":[{"text":"it is sure","label":""},{"text":"it is proved by (the fact that)","label":""}],"html":"<p>ברור וגלוי it is sure  בר׳ ס״ב ע״ב: מצא נעול בידוע שיש שם אדם מצאו פתוח בידוע שאין שם אדם. תֵּדַע מכאן ראיה it is proved by (the fact that)  פסח׳ צ״ד ע״א: כל היישוב כולו תחת כוכב אחד יושב תדע שהרי אדם נותן עינו בכוכב אחד הולך למזרח עומד כנגדו וכו׳. </p>","notation":["Marked biblical in source"]},"38966":{"h":"יָה","r":"KRU08454","alt":[],"source":"krupnik","glosses":[{"text":"exclamation of distress","label":""}],"html":"<p>מלת קריאה לצער exclamation of distress  ב״ר פצ״ב: צועק ומצטער ואומר יה יה.</p>","notation":["Marked biblical in source"]},"38967":{"h":"יְהָבָא","r":"KRU08458","alt":[],"source":"krupnik","glosses":[{"text":"load","label":""}],"html":"<p>משא load  ב״ר פע״ט: שמעון קליה דאמר לחבריה תלי הדין יהבא עלי שמעון מיניה: יהבא – משוי.</p>","notation":["ז׳"]},"38968":{"h":"יְהָבִית","r":"KRU08459","alt":["יַהֲבַת"],"source":"krupnik","glosses":[{"text":"giving","label":""}],"html":"<p>מתנה giving  תרג׳ קהל׳ ה׳ י׳: יהבית אגראה; תה׳ י״א ו׳ (מנת כוסם): יהבת כלידיהון.</p>","notation":[]},"38969":{"h":"יְהוּדָאָה","r":"KRU08460","alt":["יְהוּדַאי"],"source":"krupnik","glosses":[{"text":"Judaean, Jew","label":""}],"html":"<p>יהודי Judaean, Jew  תרג׳ אס׳ ה׳ י״ג (היהודי): יהודאה; ירוש׳ שבי׳ פ״ד ל״ה ע״א וע״ב: או יהודאי יהודאי וכו׳.</p>","notation":[]},"38970":{"h":"יְהוּדָאִיקִי","r":"KRU08461","alt":[],"source":"krupnik","glosses":[{"text":"Jewish court-house","label":""}],"html":"<p>בית דין ישראל Jewish court-house  ירוש׳ גיט׳ פ״א מ״ג ע״ב: אם אין שם יהודאיקי וכו׳.</p>","notation":["נ׳"]},"38971":{"h":"יְהוּדָאִיתָא","r":"KRU08462","alt":[],"source":"krupnik","glosses":[{"text":"Jewess","label":""}],"html":"<p>בת ישראל Jewess  איכ״ר א׳ י״א: חזיין אפיך כיהודאיתא.</p>","notation":["נ׳"]},"38972":{"h":"יְהוּדִי","r":"KRU08463","alt":[],"source":"krupnik","glosses":[{"text":"Jewish","label":""}],"html":"<p>של ישראל Jewish  מגי׳ י״ג ע״א: מאכל יהודי.</p>","notation":["ת׳","Marked biblical in source"]},"38973":{"h":"יְהוּדִיָּה","r":"KRU08464","alt":[],"source":"krupnik","glosses":[{"text":"Jewess","label":""}],"html":"<p>בת ישראל Jewess  ילק׳ אס׳ תתרנ״ב: אמאי קרי לה יהודיה.</p>","notation":["נ׳"]},"38974":{"h":"יְהוּדִינְיִי","r":"KRU08465","alt":[],"source":"krupnik","glosses":[{"text":"a woman’s name","label":""}],"html":"<p>שם אשה a woman’s name  ירוש׳ נזיר פ״ז נ״ו ע״א: כד דמכת יהודיניי אחתיה דר׳ יודן נשייא.</p>","notation":[]},"38975":{"h":"יְהוּדִית","r":"KRU08466","alt":[],"source":"krupnik","glosses":[{"text":"Jewess","label":""}],"html":"<p>בת ישראל Jewess  אסת״ר ג׳ א׳: אם אסתר יהודית היא וכו׳ נכרית היא וכו׳.</p>","notation":["נ׳"]},"38976":{"h":"יהודת","r":"KRU08467","alt":[],"source":"krupnik","glosses":[{"text":"Jewish religion","label":""}],"html":"<p>תורת ישראל Jewish religion  אסת״ר ג׳ ז׳: לא שינו אלהיהם ודתותיהם והחזיקו ביהודתן.</p>","notation":["נ׳","Source emendation: יַהֲדוּת"]},"38977":{"h":"יְהִי רָצוֹן","r":"KRU08468","alt":[],"source":"krupnik","glosses":[{"text":"be it the will of God","label":""}],"html":"<p>יתן ה׳, מי יתן be it the will of God  תענ׳ ה׳ ע״ב: יהי רצון שכל נטיעות שנוטעין ממך יהיו כמותך.</p>","notation":[]},"38978":{"h":"יְהִירוּתָא","r":"KRU08469","alt":[],"source":"krupnik","glosses":[{"text":"haughtiness","label":""}],"html":"<p>גאותנות, התרברבות haughtiness  מגי׳ י״ד ע״ב: לא יאה יהירותא לנשי.</p>","notation":["נ׳"]},"38979":{"h":"יהר","r":"KRU08472","alt":[],"source":"krupnik","glosses":[{"text":"to be haughty","label":"הִתְיָהֵר התפ׳"}],"html":"<p>הִתְיָהֵר התפ׳ התגאה, התרברב to be haughty  פס׳ ס״ו ע״ב: כל המתיהר אם חכם הוא חכמתו מסתלקת ממנו.</p>","notation":["Source marks no qal form"]},"38980":{"h":"יוּבְדָּנָא","r":"KRU08476","alt":[],"source":"krupnik","glosses":[{"text":"perdition","label":""}],"html":"<p>אבדן perdition  תרג׳ מש׳ י״א י׳ (ובאבוד רשעים רנה): וביובדנא דרשיעי חדותא.</p>","notation":["ז׳"]},"38981":{"h":"יוֹבֵילָא","r":"KRU08477","alt":[],"source":"krupnik","glosses":[{"text":"yobel-year","label":""}],"html":"<p>יובל שנת החמישים yobel-year  תרג׳ ויק׳ כ״ה י׳ (יובל היא): יובילא היא.</p>","notation":["ז׳"]},"38982":{"h":"יוּבְלָא","r":"KRU08478","alt":[],"source":"krupnik","glosses":[{"text":"lamb","label":"2"},{"text":"ram","label":"3"}],"html":"<p>1 כנ״ל. תרג׳ יב״ע במ׳ ל״ו ד׳ (ואם יהיה היובל): ואם יהי יובלא. \n2 שה lamb  ירוש׳ בר׳ פ״ט י״ג ע״ג: בערביא קורין לאימרא יובלא.\n3 איל ram  ר״ה כ״ו ע״א: כשהלכתי לערביא היו קורין לדכרא יובלא.</p>","notation":["ז׳"]},"38983":{"h":"יוּּבְקָא","r":"KRU08480","alt":[],"source":"krupnik","glosses":[{"text":"name of a brook","label":""}],"html":"<p>נחל יבק name of a brook  תרג׳ יב״ע בר׳ ל״ב כ״ג (יבק): יובקא.</p>","notation":[]},"38984":{"h":"יוֹבֶשׁ","r":"KRU08481","alt":[],"source":"krupnik","glosses":[{"text":"dry measure","label":""}],"html":"<p>מדת היבש dry measure  תרג׳ דהי״ב ד׳ ה׳: תלתא אלפין בתין ביובש.</p>","notation":["ז׳"]},"38985":{"h":"יוּבְשָׁא","r":"KRU08482","alt":[],"source":"krupnik","glosses":[{"text":"dryness","label":""}],"html":"<p>יבושת dryness  תרג׳ שופ׳ ו׳ מ׳ (ויהי חורב על הגזה): והוה יובשא על גיזתא.</p>","notation":["ז׳"]},"38986":{"h":"יוֹבְשָׁנִי","r":"KRU08483","alt":[],"source":"krupnik","glosses":[{"text":"rainless land","label":""}],"html":"<p>קרקע יבש ביותר rainless land  תענ׳ י׳ ע״ב: טובעני ולא יובשני.</p>","notation":["ז׳"]},"38987":{"h":"יוּ״ד","r":"KRU08485","alt":[],"source":"krupnik","glosses":[{"text":"the tenth letter of the Alphabet","label":""}],"html":"<p>האות העשירית שבאלפבית the tenth letter of the Alphabet  תענ׳ ב׳ ע״ב: הרי מ״ם יו״ד מ״ם הרי מים.</p>","notation":[]},"38988":{"h":"יוּד","r":"KRU08486","alt":["יוּדָא"],"source":"krupnik","glosses":[{"text":"names of Amoraim","label":""}],"html":"<p>שמות אמוראים names of Amoraim  תענ׳ כ״ב ע״ב: רמי בר רב יוד; זבח׳ נ״ה ע״ב: ר׳ יודא בר צרדייה.</p>","notation":[]},"38989":{"h":"יוּדַאי","r":"KRU08487","alt":[],"source":"krupnik","glosses":[{"text":"Jew","label":""}],"html":"<p>Jew  ירוש׳ ברכ׳ פ״ב ה׳ ע״א: עובדא הוה בחד יודאי וכו׳ עבר חד ערבי וכו׳. </p>","notation":["ז׳"]},"38990":{"h":"יוּדָה","r":"KRU08489","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ בר׳ פ״ג ו׳ ע״א: ר׳ יודה אומר.</p>","notation":[]},"38991":{"h":"יוּדֵן","r":"KRU08491","alt":[],"source":"krupnik","glosses":[{"text":"who, what) is this","label":""}],"html":"<p>זהו (who, what) is this  תרג׳ שני אס׳ ז׳ ה׳ (מי הוא זה ואי זה הוא): מה יודן ובר מן יודן.</p>","notation":["מה״י"]},"38992":{"h":"יוּדָן","r":"KRU08492","alt":[],"source":"krupnik","glosses":[{"text":"name of Amoraim","label":""}],"html":"<p>שם אמוראים name of Amoraim  ירוש׳ בר׳ פ״ד ה׳ ע״א: ר׳ יודן בריה דר׳ אייבו.</p>","notation":[]},"38993":{"h":"יוֹדְפָאָה","r":"KRU08493","alt":[],"source":"krupnik","glosses":[{"text":"of Jotapata in Galilee","label":""}],"html":"<p>איש יודפת of Jotapata in Galilee  זבח׳ ק״י ע״ב: ר׳ מנחם יודפאה.</p>","notation":[]},"38994":{"h":"יוֹדְפָת","r":"KRU08494","alt":[],"source":"krupnik","glosses":[{"text":"Jotapata, a town in Galilee","label":""}],"html":"<p>עיר בגליל Jotapata, a town in Galilee  ערכ׳ פ״ט מ״ו: ויודפת הישנה.</p>","notation":[]},"38995":{"h":"יוֹהֲרָא","r":"KRU08495","alt":[],"source":"krupnik","glosses":[{"text":"precious stone","label":""}],"html":"<p>אבן טובה precious stone  תרג׳ שה״ש ז׳ ב׳ (כמו חלאים): כיוהרין.</p>","notation":["ז׳"]},"38996":{"h":"יוּהֲרָא","r":"KRU08496","alt":[],"source":"krupnik","glosses":[{"text":"haughtiness","label":""}],"html":"<p>גאותנות, יהירות haughtiness  סוכה כ״ו ע״ב: אם בא להחמיר על עצמו מחמיר ולית ביה משום יוהרא.</p>","notation":["ז׳"]},"38997":{"h":"יְוָונָאָה","r":"KRU08497","alt":[],"source":"krupnik","glosses":[{"text":"Greek","label":""}],"html":"<p>יוני Greek  תרג׳ יואל ד׳ ו׳ (יונים): יוונאי.</p>","notation":["ז׳"]},"38998":{"h":"יְוָונִי","r":"KRU08498","alt":[],"source":"krupnik","glosses":[{"text":"Grecian","label":""}],"html":"<p>של יון Grecian  ב״ק פ״ב ע״ג – פ״ג ע״א: בארץ ישראל לשון סורסי למה או לשון הקודש או לשון יווני.</p>","notation":["ת׳"]},"38999":{"h":"יוֹזִיף","r":"KRU08499","alt":[],"source":"krupnik","glosses":[{"text":"debtor","label":""}],"html":"<p>לוה debtor  תרג׳ מש׳ כ״ב ז׳ (עבד לוה לאיש מלוה): ועבדא יוזיף לגברא מוזפנא.</p>","notation":["ז׳"]},"39000":{"h":"יוֹחַי","r":"KRU08500","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  שבת ל״ג ע״ב: ר׳ שמעון בן יוחי. </p>","notation":["שם איש"]},"39001":{"h":"יוֹחָנָא","r":"KRU08501","alt":[],"source":"krupnik","glosses":[{"text":"name of Amoraim","label":"1"},{"text":"name of a place","label":"2"},{"text":"a species of locusts","label":"3"}],"html":"<p>1 שם אמוראים name of Amoraim  חול׳ קל״ג ע״א: רבא ורב ספרא איקלעו לבי מר יוחנא בריה דרב חנא בר אדא ואמרי לה לבי מר יוחנא בריה דרב חנא בר ביזנא.\n2 שם מקום name of a place  ב״ר פכ״ה: שילו חטא ויוחנא משתלמא\n3 מין ארבה a species of locusts  חול׳ ס״ה ע״א: יוחנא ירושלמית.</p>","notation":["ז׳"]},"39002":{"h":"יוֹחָנִי","r":"KRU08503","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":"1"},{"text":"a woman’s name","label":"2"}],"html":"<p>1  a man’s name  מנח׳ פ״ה ע״א: אמרי ליה יוחני וממרא למשה וכו׳.\n2 שם אשה a woman’s name  סוטה כ״ב ע״ב: יוחני בת רטיבי.</p>","notation":[]},"39003":{"h":"יוּחָס","r":"KRU08504","alt":[],"source":"krupnik","glosses":[{"text":"genealogy","label":""}],"html":"<p>יחש, התיחסות, תולדות genealogy  יבמ׳ פ״ד מי״ג: מצאתי מגילת יוחסין בירושלים וכתוב בה איש פלוני ממזר מאשת איש.</p>","notation":["ז׳"]},"39004":{"h":"יוּכְלָא","r":"KRU08506","alt":[],"source":"krupnik","glosses":[{"text":"power, ability","label":""}],"html":"<p>יבולת power, ability  תרג׳ במ׳ י״ד ט״ז (מבלתי יכולת): מדלית יוכלא וכו׳.</p>","notation":["ז׳"]},"39005":{"h":"יול","r":"KRU08508","alt":[],"source":"krupnik","glosses":[{"text":"to be brought","label":"הוּוַל הפ׳,"}],"html":"<p>הוּוַל הפ׳, הובל והובא to be brought  תוס׳ צוק׳ טהר׳ ח׳ ז׳: והלה מוול או כפות.</p>","notation":["Source marks no qal form"]},"39006":{"h":"יוֹלְדִים","r":"KRU08509","alt":[],"source":"krupnik","glosses":[{"text":"parents","label":""}],"html":"<p>הורים, אב ואם parents  כת׳ פ״ז מ״ו: המקללת יולדיו בפניו.</p>","notation":["ז״ר"]},"39007":{"h":"יוּלַדְתָּא","r":"KRU08510","alt":[],"source":"krupnik","glosses":[{"text":"midwife","label":""}],"html":"<p>מילדת midwife  תרג׳ ירוש׳ שמ׳ א׳ ט״ו (המילדות): יולדתא.</p>","notation":["נ׳"]},"39008":{"h":"יוֹלִימְנָא","r":"KRU08512","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  פסיק״ר ז׳: רַ׳ יולימנא כן עבדי.</p>","notation":[]},"39009":{"h":"יוֹם","r":"KRU08515","alt":[],"source":"krupnik","glosses":[{"text":"sun","label":""}],"html":"<p>שמש sun  ב״ר פ״ו: ג׳ דברים קולן הולך מסוף העולם ועד סופו וכו׳ היום והגשמים והנפש בשעה שהיא יוצאה מן הגוף.</p>","notation":["Marked biblical in source"]},"39010":{"h":"יוֹם הוֹשַׁעְנָא","r":"KRU08516","alt":[],"source":"krupnik","glosses":[{"text":"the seventh day of the feast of tabernacles","label":""}],"html":"<p>הושענא רבה, יום אחרון לחול המועד בסוכות the seventh day of the feast of tabernacles  ויק״ר פל״ז: אלין אתרוגין דיהודאי מצלין עמהון ביום הושענא.</p>","notation":[]},"39011":{"h":"יְמוֹת הַגְּשָׁמִים","r":"KRU08517","alt":[],"source":"krupnik","glosses":[{"text":"rainy season","label":""}],"html":"<p>תקופת הגשמים שבכל שנה rainy season  ב״מ פ״ח מ״ו: המשכיר בית לחבירו בימות הגשמים אינו יכול להוציא מן החג ועד הפסח.</p>","notation":[]},"39012":{"h":"יְמוֹת הַחַמָּה","r":"KRU08518","alt":[],"source":"krupnik","glosses":[{"text":"summer season","label":"1"},{"text":"the solar year","label":"2"}],"html":"<p>1 תקופת הקיץ שבכל שנה summer season  תוס׳ טהר׳ ז׳ ח׳: אלו הן ימות החמה משתיעקר תבואה מתוכה.\n2 שנה למנין חמה the solar year  ב״ר פל״ג: י״א יום שימות החמה יתירים על ימות הלבנה.</p>","notation":[]},"39013":{"h":"יְמוֹת הַלְּבָנָה","r":"KRU08519","alt":[],"source":"krupnik","glosses":[{"text":"the lunar year","label":""}],"html":"<p>שנה למנין לבנה the lunar year  ב״ר פל״ג: שימות החמה יתירים על ימות הלבנה י״א יום.</p>","notation":[]},"39014":{"h":"יְמֵי בְרֵאשִׁית","r":"KRU08520","alt":[],"source":"krupnik","glosses":[{"text":"the days of creation","label":""},{"text":"after a time","label":""}],"html":"<p>ימי הבריאה the days of creation  ירוש׳ מעש׳ פ״ה נ״ד ע״א: אין מרובע מששת ימי בראשית. לְיָמִים לאחר זמן after a time  פסי״ר כ״א: למלך שכעס על מטרונתו וכו׳ לימים בקש להחזירה. </p>","notation":[]},"39015":{"h":"יוֹמָא","r":"KRU08521","alt":[],"source":"krupnik","glosses":[{"text":"day","label":"1"},{"text":"sun","label":"2"},{"text":"name of a treatise of the Talmud on the order of exercises of the Day of Atonement","label":"3"}],"html":"<p>1 יום day  ברכ׳ ב׳ ע״ב: איערב שמשא ואדכי יומא.\n2 שמש sun  חול׳ ס׳ ע״א: אוקמיה להדי יומא בתקופת תמוז.\n3 שם מסכת בסדר מועד הדנה בהלכות יום כפור name of a treatise of the Talmud on the order of exercises of the Day of Atonement  יומא י״ד ע״ב: מאן תנא סדר יומא.</p>","notation":["ז׳"]},"39016":{"h":"יוֹמָא דְכִיּפּוּרֵי","r":"KRU08522","alt":[],"source":"krupnik","glosses":[{"text":"Day of Atonement","label":""}],"html":"<p>יום הכפורים Day of Atonement  יומא י״ט ע״כ: והא האידנא יומא דכפורי הוא וכו׳.</p>","notation":[]},"39017":{"h":"יוֹמָא חָרָא","r":"KRU08523","alt":[],"source":"krupnik","glosses":[{"text":"to-morrow","label":""}],"html":"<p>מחר to-morrow  תרג׳ דה״ב כ׳ ט״ז (מחר): יומא חרא.</p>","notation":[]},"39018":{"h":"יוֹמָא טָבָא","r":"KRU08524","alt":[],"source":"krupnik","glosses":[{"text":"Holy Day","label":""}],"html":"<p>חג, יום טוב Holy Day  ביצה ד׳ ע״א: מיומא טבא לחבריה.</p>","notation":[]},"39019":{"h":"יוֹמָא רַבָּא","r":"KRU08525","alt":[],"source":"krupnik","glosses":[{"text":"Day of Atonement","label":""}],"html":"<p>יום הכפורים Day of Atonement  ר״ה כ״א ע״א: בסים תבשילא דבבלאי ביומא רבא דמערבא.</p>","notation":[]},"39020":{"h":"יוֹמָחְרָא","r":"KRU08527","alt":["יוֹמָחֲרָן"],"source":"krupnik","glosses":[{"text":"to-morrow","label":""}],"html":"<p>מחר to-morrow  תרג׳ שמ׳ י״ט י׳ (היום ומחר): יומא דין ויומחרא; ויק׳ ז׳ ט״ז (וממחרת): וביומחרו.</p>","notation":[]},"39021":{"h":"יוֹמָנָא","r":"KRU08528","alt":[],"source":"krupnik","glosses":[{"text":"this life","label":"1"},{"text":"to-day","label":"2"}],"html":"<p>1  this life  תרג׳ יב״ע דב׳ כ״ו י״ח: עלמא יומנא.\n2  to-day  שם כ״ז א׳ (היום): יומנא.</p>","notation":[]},"39022":{"h":"יוֹן","r":"KRU08529","alt":["יוֹנָא"],"source":"krupnik","glosses":[{"text":"dove","label":""}],"html":"<p>עוף היונה dove  סנה׳ כ״ה ע״א: אי תקדמיה יונך ליון; בר׳ נ״ו ע״א: דנקטי תרי יוני ופרחי להו.</p>","notation":["ז׳"]},"39023":{"h":"יְוָנָאָה","r":"KRU08530","alt":[],"source":"krupnik","glosses":[{"text":"Greek","label":""}],"html":"<p>יוני Greek  תרג׳ ש״א ב׳ ד׳: קשתת דגברי יונאי אתברין.</p>","notation":["ז׳"]},"39024":{"h":"יוֹנָה","r":"KRU08531","alt":[],"source":"krupnik","glosses":[{"text":"ebony","label":"1"},{"text":"name of several Amoraim","label":"2"}],"html":"<p>1 עץ הָבנים ebony  שבת קכ״ט ע״א: פתורא דיונה.\n2 שם אמוראים name of several Amoraim  תעני׳ כ״ג ע״ב: תקיפי דארעא דישראל כגון ר׳ יונה אבוה דרבי מני; ירוש׳ שבי׳ פ״ד ל״ה ע״א: ר׳ יונה בשם ר׳ חייה בר אשי.</p>","notation":["Marked biblical in source"]},"39025":{"h":"יוֹנוֹס","r":"KRU08532","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>שם איש a man’s name  תנח׳ כי תשא י״ט: יונוס וימבריס.</p>","notation":[]},"39026":{"h":"יְוֵנִי","r":"KRU08533","alt":[],"source":"krupnik","glosses":[{"text":"muddy","label":""}],"html":"<p>של רבב ורפש muddy  מקוא׳ פ״ט מ״ב: וגץ יוני אלו יתדות הדרכים.</p>","notation":["ת׳"]},"39027":{"h":"יְוָנִי","r":"KRU08534","alt":[],"source":"krupnik","glosses":[{"text":"Grecian","label":""}],"html":"<p>של יון Grecian  ירוש׳ גיט׳ פ״ט נ׳ ע״ד: כתב יוני וכו׳ עד יוני.</p>","notation":["ת׳"]},"39028":{"h":"יְוָנִית","r":"KRU08535","alt":[],"source":"krupnik","glosses":[{"text":"Greek (language)","label":""}],"html":"<p>לשון יונית Greek (language)  ירוש׳ סוטה פ״ט כ״ד ע״ג: מותר לאדם ללמד את בתו יונית מפני שהוא תכשיט לה.</p>","notation":["נ׳"]},"39029":{"h":"יוֹנְקָא","r":"KRU08536","alt":[],"source":"krupnik","glosses":[{"text":"suckling","label":""}],"html":"<p>יונק suckling  תרג׳ תה׳ ח׳ ג׳ (יונקים): יונקיא.</p>","notation":["ז׳"]},"39030":{"h":"יוֹנְתָא","r":"KRU08537","alt":[],"source":"krupnik","glosses":[{"text":"dove","label":""}],"html":"<p>יונה dove  תרג׳ יב״ע בר׳ ח׳ ח׳ (היונה:) יונתא דבייתא.</p>","notation":["נ׳"]},"39031":{"h":"יוֹסָה","r":"KRU08538","alt":["יוּסְטָא","יוּסְטִי","יוּסְטִינָה","יוּסְטִינִי","יוסטתה"],"source":"krupnik","glosses":[{"text":"names of Amoraim","label":""}],"html":"<p>שמות אמוראים names of Amoraim  ירוש׳ תענ׳ פ״ד ס״ח ע״ג: ר׳ יוסה בר אבא; שקל׳ פ״ב מ״ו ע״ג; ר׳ יוסטא; עיר׳ פ״ו כ״ג ע״ג: ר׳ יוסטי; ב״ב פ״ח ט״ז ע״ב: יוסטיני; כת׳ פ״ט ל״ב ע״ד: ר׳ יוסטתה וכו׳ רבנין דר׳ יוסטינה.</p>","notation":[]},"39032":{"h":"יוֹסֵי","r":"KRU08539","alt":[],"source":"krupnik","glosses":[{"text":"name of Tannaim and Amoraim","label":""}],"html":"<p>שם תנאים ואמוראים name of Tannaim and Amoraim  אבות פ״א מ״ד: יוסי בן יועזר איש צרידה ויוסי בן יוחנן איש ירושלם.</p>","notation":[]},"39033":{"h":"יוֹסִינָא","r":"KRU08540","alt":["יוֹסִינָה","יוֹסֵינְיָה","יוֹסָנָה","יוֹסְנִי"],"source":"krupnik","glosses":[{"text":"names of men","label":""}],"html":"<p>שמות אנשים names of men  ירוש׳ יבמ׳ פי״ג י״ג ע״ג: ר׳ שמעון בן יוסינא; ירוש׳ מג׳ פ״ד ע״ה ע״ב: בן יוסינה; במ״ר פי״ג: בן יוסיניה: שהש״ר ה׳ א׳: יוסנה; פסיק״ר ה׳: יוסני.</p>","notation":[]},"39034":{"h":"יוּסְתִּינְיָא","r":"KRU08542","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  זבח׳ קי״ד ע״א: חייא מיוסתיניא. </p>","notation":["שם מקום"]},"39035":{"h":"יוֹעֶזֶר","r":"KRU08543","alt":[],"source":"krupnik","glosses":[{"text":"Maiden-hair","label":""}],"html":"<p>מין צמח Maiden-hair  שבת פי״ד מ״ג: אוכל הוא את יועזר ושותה אבוב רועה.</p>","notation":["ז׳"]},"39036":{"h":"יוֹפִיאֵל","r":"KRU08544","alt":[],"source":"krupnik","glosses":[{"text":"name of an angel","label":""}],"html":"<p>שם מלאך name of an angel  תרג׳ יב״ע דב׳ ל״ד ו׳: יופיאל.</p>","notation":[]},"39037":{"h":"יוֹפְיוּת","r":"KRU08545","alt":[],"source":"krupnik","glosses":[{"text":"beauty","label":""}],"html":"<p>יופי, נוי beauty  ילק׳ בר׳ ס״א: יופיותו של יפת.</p>","notation":["נ׳"]},"39038":{"h":"יוֹצְאָנִית","r":"KRU08546","alt":[],"source":"krupnik","glosses":[{"text":"loving to go out","label":""}],"html":"<p>אשה שדרכה לצאת הרבה loving to go out  ב״ר פמ״ה: ד׳ מדות נאמרו בנשים וכו׳ יוצאניות ותצא דינה.</p>","notation":["נ׳"]},"39039":{"h":"יוֹצֵאת הַחוּץ","r":"KRU08547","alt":[],"source":"krupnik","glosses":[{"text":"prostitute","label":""}],"html":"<p>זונה prostitute  כל׳ פכ״ח מ״ט: חליק של יוצאת החוץ העשוי כסבכה.</p>","notation":["נ׳"]},"39040":{"h":"יוּצְפָּא","r":"KRU08548","alt":[],"source":"krupnik","glosses":[{"text":"care, trouble","label":""}],"html":"<p>דאגה care, trouble  תרג׳ יהוש׳ כ״ב כ״ג (מדאגה): מיוצפא.</p>","notation":["נ׳"]},"39041":{"h":"יוֹקֶר","r":"KRU08551","alt":[],"source":"krupnik","glosses":[{"text":"high price","label":""}],"html":"<p>מחיר רב high price  מע״ש פ״ד מ״א: המוליך פירות מעשר שני ממקום היוקר למקום הזול או ממקום הזול למקום היוקר.</p>","notation":["ז׳"]},"39042":{"h":"יוֹקְרָא","r":"KRU08552","alt":[],"source":"krupnik","glosses":[{"text":"respect","label":"1"},{"text":"weight, heaviness","label":"2"}],"html":"<p>1 כבוד ויקר respect  תרג׳ איוב כ״ח י״ז: לית איפשר דתשתכח בזילותא אילהן ביוקרא.\n2 כובד weight, heaviness  מנח׳ צ״ד ע״ב: אגב יוקרא דלחם.</p>","notation":["ז׳"]},"39043":{"h":"יוֹקְרָא דְלִיבָּא","r":"KRU08553","alt":[],"source":"krupnik","glosses":[{"text":"heart-disease","label":""}],"html":"<p>מין מחלת הלב heart-disease  שבת ק״מ ע״ב: חש ביוקרא דליבא.</p>","notation":[]},"39044":{"h":"יוֹקֶרֶת","r":"KRU08554","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  תענ׳ כ״ג ע״ב: ר׳ יוסי דמן יוקרת. </p>","notation":["שם מקום"]},"39045":{"h":"יוֹרְדְּנָא","r":"KRU08555","alt":[],"source":"krupnik","glosses":[{"text":"Jordan, the river of Palestine","label":""}],"html":"<p>נהר הירדן Jordan, the river of Palestine  תרג׳ בר׳ א׳ ה׳ (בעבר הירדן): בעברא דיורדנא.</p>","notation":[]},"39046":{"h":"יוֹרֶדֶת","r":"KRU08556","alt":[],"source":"krupnik","glosses":[{"text":"torrent","label":""}],"html":"<p>פלג היורד במדרון torrent  תוס׳ פרה ה׳ (ט׳) ב׳: יורדת הצלמון.</p>","notation":["נ׳"]},"39047":{"h":"יוֹרֶה","r":"KRU08557","alt":[],"source":"krupnik","glosses":[{"text":"early season, spring","label":""}],"html":"<p>עונת מטר היורה, אביב early season, spring  תנח׳ חיי ז׳: אם זרעת ביורה אל תעמוד במלקוש.</p>","notation":["Marked biblical in source"]},"39048":{"h":"יוֹרָה","r":"KRU08558","alt":[],"source":"krupnik","glosses":[{"text":"kettle","label":""}],"html":"<p>דוד, קלחת kettle  שבת ק״ב ע״ב: כירה קטנה לשפות עליה יורה קטנה.</p>","notation":["נ׳"]},"39049":{"h":"יוֹרְכָא","r":"KRU08559","alt":[],"source":"krupnik","glosses":[{"text":"a precious stone","label":""}],"html":"<p>אבן טובה a precious stone  תרג׳ יב״ע דב׳ ל״ד ו׳: יורכין.</p>","notation":["ז׳"]},"39050":{"h":"יוּרְקָא","r":"KRU08560","alt":[],"source":"krupnik","glosses":[{"text":"green","label":""}],"html":"<p>ירוק green  פס׳ ל׳ ע״ב: בין חיורא בין אוכמי ובין יורקי.</p>","notation":["ת׳"]},"39051":{"h":"יוּרְקָמִי","r":"KRU08561","alt":[],"source":"krupnik","glosses":[{"text":"name of an angel","label":""}],"html":"<p>שם מלאך name of an angel  פסח׳ קי״ח ע״א: יורקמי שר הברד.</p>","notation":[]},"39052":{"h":"יוּרְקָנָא","r":"KRU08562","alt":[],"source":"krupnik","glosses":[{"text":"mildew","label":""}],"html":"<p>ירקון בתבואה mildew  תרג׳ דהי״ב ו׳ כ״ח (שדפון וירקון): שודפנא ויורקנא.</p>","notation":["ז׳"]},"39053":{"h":"יוֹשֶׁן","r":"KRU08563","alt":[],"source":"krupnik","glosses":[{"text":"former condition","label":""}],"html":"<p>המ ַ עמד הקודם former condition  יומא ס״ט ע״ב: למה נקרא שמם אנשי כנסת הגדולה שהחזירו העטרה ליושנה.</p>","notation":["ז׳"]},"39054":{"h":"יוּתָא","r":"KRU08564","alt":[],"source":"krupnik","glosses":[{"text":"the constellation called the Great Bear (Ursa Major)","label":""}],"html":"<p>כוכבי עיש the constellation called the Great Bear (Ursa Major)  בר׳ נ״ח ע״ב: עיש – יותא.</p>","notation":["ז׳"]},"39055":{"h":"יוֹתְפָיָיה","r":"KRU08565","alt":[],"source":"krupnik","glosses":[{"text":"of Yotapata","label":""}],"html":"<p>מעיר יודפה of Yotapata  ירוש׳ סוכה פ״ד נ״ד ע״ג: מנחם יותפייה.</p>","notation":[]},"39056":{"h":"יוֹתֵריוֹתֵר מִדַּאי","r":"KRU08566","alt":[],"source":"krupnik","glosses":[{"text":"more than enough, too much","label":""},{"text":"especially","label":""}],"html":"<p>יתר על המדה, די והותר more than enough, too much  ב״ב ס׳ ע״ב: שלא להתאבל כל עיקר אי אפשר וכו׳ ולהתאבל יותר מדאי אי אפשר שאין גוזרין גזירה על הצבור אלא א״כ רוב הצבור יכולין לעמוד בה. בְּיוֹתֵר תה״פ ביחוד, בפרט especially  פסיק״ר ל״א: והיתה חביבה עליו ביותר. </p>","notation":["Marked biblical in source"]},"39057":{"h":"יוּתְרָן","r":"KRU08567","alt":["יוּתְרָנָא"],"source":"krupnik","glosses":[{"text":"advantage, profit","label":""}],"html":"<p>יתרון, ריוח advantage, profit  תרג׳ מש׳ כ״ח ג׳ (מטר סוחף ואין לחם): מטרא חביטא דלית ביה יותרן; שם כ״א ה׳ (מחשבות חרוץ אך למותר): מחשבתיה דגביין ליותרנא.</p>","notation":[]},"39058":{"h":"יְזוּפְתָּא","r":"KRU08569","alt":[],"source":"krupnik","glosses":[{"text":"a loan","label":""}],"html":"<p>מִלוה, הלוואה a loan  מו״ק כ״ח ע״ב: ויזופתא יזיף.</p>","notation":["נ׳"]},"39059":{"h":"יְזַף","r":"KRU08570","alt":[],"source":"krupnik","glosses":[{"text":"to borrow","label":""},{"text":"to lend","label":""}],"html":"<p>לוה to borrow  ב״מ ס״ד ע״א: כי יזיף פלוני פשיטי ממך. אוֹזִיף  אפ׳, הלוה to lend  בכ׳ ח׳ ע״ב: גברא דאוזיף וטריף מאי חזא דהדר טריף. </p>","notation":["פ״י"]},"39060":{"h":"יַזְפָא","r":"KRU08571","alt":[],"source":"krupnik","glosses":[{"text":"debtor","label":""}],"html":"<p>לווה debtor  תרג׳ ישע׳ כ״ד ב׳ (כמלוה כלוה): יזפא כמוזפא.</p>","notation":["ז׳"]},"39061":{"h":"יָזֵק","r":"KRU08572","alt":[],"source":"krupnik","glosses":[{"text":"name of a river in Babylonia","label":""}],"html":"<p>שם נהר בבבל name of a river in Babylonia  ירוש׳ קיד׳ פ״ד ס״ה ע״ד: נהר יזק.</p>","notation":[]},"39062":{"h":"יִחֵד","r":"KRU08576","alt":[],"source":"krupnik","glosses":[{"text":"to designate","label":""},{"text":"to declare the unity of God","label":""},{"text":"to leave persons alone in a special room","label":""},{"text":"to be conferred, to be especially addressed","label":""},{"text":"to be alone with","label":""}],"html":"<p>1) קבע והועיד to designate  מכי׳ בא ה׳: יחד הכתוב מצוה הזאת ואמרה ענין בפני עצמו. 2) הכריז על האחדות to declare the unity of God  שהש״ר ב׳ ט״ז: הוא אמר לי מי כעמך ישראל גוי אחד בארץ ואני מיחדת שמו בכל יום פעמים. 3) שם שני אנשים לבדם במדור אחד to leave persons alone in a special room  תוס׳ כת׳ א׳ ד׳: היו מייחדין את החתן ואת הכלה שעה אחת. הִתְיַחֵד התפ׳, 1) נקבע ונועד ביחוד to be conferred, to be especially addressed  שמו״ר פ״ז: בתחלה היה ראוי הדיבור להתיחד עליו בפני עצמו. 2) היה לבדו עם פלוני to be alone with  קיד׳ פ״ד מי״ב: לא יתיחד איש אחד עם שתי נשים אבל אשה אחת מתיחדת עם שני אנשים. </p>","notation":["Marked biblical in source"]},"39063":{"h":"יַחֵד","r":"KRU08577","alt":[],"source":"krupnik","glosses":[{"text":"to concentrate","label":""},{"text":"to be joined","label":""}],"html":"<p>1) ריכז, צמצם to concentrate  תרג׳ תה׳ פ״ו י״א: יחד לבבי. 2) עי׳ יִחֵד 1. מכות י״ח ע״א: ליחודי להו לאוי לכל חד וחד. אִתְיַחֵד, אִיַּחֵד אתפ׳, 1) התחבר והתאחד to be joined  תרג׳ יב״ע בר׳ מ״ט ו׳ (לא תחד כבודי): לא אתיחד יקרי. 2) עי׳ הִתְיַחֵד. סנה׳ ל״ז ע״א: אמריתו נדה שרי לייחודי בהדי גברא. </p>","notation":["פַעל"]},"39064":{"h":"יִחוּד","r":"KRU08579","alt":[],"source":"krupnik","glosses":[{"text":"private meeting","label":""}],"html":"<p>שהית שנַים לבדם במדור אחד private meeting  ירוש׳ גיט׳ פ״ז מ״ח ע״ד: נתייחדה עמו בפני שנים וכו׳ אין זה יחוד.</p>","notation":["ז׳"]},"39065":{"h":"יִחוּד הַשֵּׁם","r":"KRU08580","alt":[],"source":"krupnik","glosses":[{"text":"declaration of the unity of God","label":""},{"text":"privately","label":""},{"text":"exactly","label":""}],"html":"<p>הכרזת אחדות הבורא declaration of the unity of God  פסיק׳ זוטרתא נצבים: ולדבקה בו זה יחוד השם. בְּיִחוּד תה״פ 1) ביחידות privately  ביצה כ״ב ע״ב: אמר רב שאילית את רבי ביחוד. 2) בדיוק, בודאות exactly  שקל׳ פ״ו מ״ב: וידעו ביחוד ששם הארון נגנז. ועי׳ יִיחוּד. </p>","notation":[]},"39066":{"h":"יִחוּדָא","r":"KRU08581","alt":[],"source":"krupnik","glosses":[{"text":"unity","label":""}],"html":"<p>אחדות ויחידות unity  תרג׳ שה״ש ח׳ ט׳: יחוד שמיה דמרי עלמא.</p>","notation":["ז׳"]},"39067":{"h":"יִחוּס","r":"KRU08582","alt":[],"source":"krupnik","glosses":[{"text":"genealogy","label":""}],"html":"<p>יחש, תולדות genealogy  במ״ר פי״ג: אברהם שהיה עיקר היחוס.</p>","notation":["ז׳"]},"39068":{"h":"יִחוּסָא","r":"KRU08583","alt":[],"source":"krupnik","glosses":[{"text":"family","label":"2"},{"text":"noble descent","label":"3"}],"html":"<p>1 כנ״ל. תרג׳ יב״ע בר׳ ה׳ א׳: ספר יחוס תולדות אדם. \n2 משפחה family  שם שם כ״ד מ״א (למשפחתי): לבית יחוסי.\n3 יחוס הגון noble descent  קיד׳ ע״א ע״ב: שתיקותיה דבבל היינו יחוסא.</p>","notation":["ז׳"]},"39069":{"h":"יִחוּף","r":"KRU08584","alt":[],"source":"krupnik","glosses":[{"text":"bare-footedness","label":""}],"html":"<p>הליכה בלי נעלים bare-footedness  יומא ע״ז ע״א: כדי שלא יבוא רגלך לידי יחוף.</p>","notation":["ז׳"]},"39070":{"h":"יָחוֹפָה","r":"KRU08585","alt":[],"source":"krupnik","glosses":[{"text":"bare-footed","label":""}],"html":"<p>יחף bare-footed  איכ״ר א׳ ז׳: כד יחופה ברא מדכר שלותא דביתיה דאבוי.</p>","notation":["ת׳"]},"39071":{"h":"יִחוּר","r":"KRU08586","alt":[],"source":"krupnik","glosses":[{"text":"young shoot","label":""}],"html":"<p>ענף רך young shoot  עוקצ׳ פ״ג מ״ח: יחור של תאנה שנפשח ומעורה בקליפה.</p>","notation":["ז׳"]},"39072":{"h":"יַחֲטָא","r":"KRU08587","alt":[],"source":"krupnik","glosses":[{"text":"accuser","label":""}],"html":"<p>משטין, קטיגור accuser  תרג׳ זכ׳ ג׳ ב׳ (השטן): יחטא.</p>","notation":["ז׳"]},"39073":{"h":"יחי","r":"KRU08588","alt":[],"source":"krupnik","glosses":[{"text":"to hurry","label":"אוֹחִי הפ׳,"}],"html":"<p>אוֹחִי הפ׳, החיש, מיהר to hurry  תרג׳ שמ׳ ב׳ י״ח (מדוע מהרתן בא): מא דין אוחיתין למיתי.</p>","notation":["Source marks no qal form"]},"39074":{"h":"יָחִיד","r":"KRU08589","alt":[],"source":"krupnik","glosses":[{"text":"single","label":""},{"text":"select","label":""},{"text":"the Unique, God","label":""},{"text":"privately","label":""}],"html":"<p>1) פרט, אחד מן הצבור single  זבח׳ פ״ה מ״ג: חטאת הצבור והיחיד. 2) נבחר ומצויין select  ירוש׳ בר׳ פ״ב ה׳ ע״ד: לא כל הרוצה לעשות עצמו יחיד עושה תלמיד חכם עושה. 3) כנוי לאלהים the Unique, God  ב״ר פכ״א: כאחד — ביחידו של עולם. בְּיָחִיד תה״פ ביחידות privately  ירוש׳ כת׳ פ״ז ל״א ע״ב: על מנת שתאמרי לאיש פלוני מה שאמרתי ביחיד או מה שאמרת לי ביחיד. </p>","notation":["Marked biblical in source"]},"39075":{"h":"יְחִידָא","r":"KRU08590","alt":[],"source":"krupnik","glosses":[{"text":"single, only","label":""}],"html":"<p>יחיד, אחד single, only  תרג׳ מש׳ ד׳ ג׳ (ויחיד לפני אמי): ויחידא קדם אמי.</p>","notation":["ת׳"]},"39076":{"h":"יְחִידָאָה","r":"KRU08591","alt":[],"source":"krupnik","glosses":[{"text":"particular","label":"2"}],"html":"<p>1 כנ״ל. פס׳ ק״ג ע״ב: לא יחידאה אנא. \n2 מיוחד במינו particular  נדר׳ נ״א ע״א: יספרתא יחידאה.</p>","notation":["ת׳"]},"39077":{"h":"יְחִידִי","r":"KRU08593","alt":[],"source":"krupnik","glosses":[{"text":"single, lonely","label":""}],"html":"<p>אחד בפני עצמו single, lonely  ב״ר פצ״ט: כל החיות מהלכות זוגות זוגות והנחש אינו מהלך בדרך אלא יחידי.</p>","notation":["ת׳"]},"39078":{"h":"יָחַם","r":"KRU08594","alt":[],"source":"krupnik","glosses":[{"text":"to be in hot passion","label":"הִתְיַחֵם התפ׳,"}],"html":"<p>הִתְיַחֵם התפ׳, התחמם בתאוה to be in hot passion  במ״ר פיט: למוד מצאנו של יעקב אבינו שמן המקלות היו מתיחמות.</p>","notation":["Marked biblical in source"]},"39079":{"h":"יַחֵם","r":"KRU08595","alt":[],"source":"krupnik","glosses":[{"text":"to heat","label":""}],"html":"<p>חימם, עורר תאות המין to heat  תרג׳ בר׳ ל׳ מ״א (ליחמנה): ליחמותהן. אִתְיַחַם אתפ׳, עי׳ הִתְיַחֵם. שם שם ל״ט (ויחמו הצאן): ואתיחמא ענא. </p>","notation":["פַעל"]},"39080":{"h":"יַחֲמָא","r":"KRU08596","alt":[],"source":"krupnik","glosses":[{"text":"poison","label":""}],"html":"<p>ארס poison  תרג׳ חבק׳ ב׳ ט״ו: וזליף כיחמא.</p>","notation":["ז׳"]},"39081":{"h":"יִחֵס","r":"KRU08598","alt":[],"source":"krupnik","glosses":[{"text":"to trace the connection of descent","label":"פיעל,"},{"text":"to claim a pedigree","label":"הִתְיַחֵס התפ׳, 1"},{"text":"to be recorded in genealogical list","label":"הִתְיַחֵס התפ׳, 2"}],"html":"<p>פיעל, יחש, בירר את מוצאו ומולדתו to trace the connection of descent  סנה׳ פ״ה ע״ב: התחילו שבטים מבזים אותו וכו׳ בא הכתוב ויחסו פנחס בן אלעזר בן אהרן הכהן.\nהִתְיַחֵס התפ׳, 1 חשב עצמו למיוחס אחרי משפחה פלונית to claim a pedigree  תוס׳ פאה ד׳ י״א: בית נבלטא היתה בירושלים מתיחסת עם ארונה היבוסי.\nהִתְיַחֵס התפ׳, 2 נזכר בספר יוחסין to be recorded in genealogical list  ירוש׳ יבמ׳ פ״ב ד׳ ע״א: על ידי שכיבד זקינו זכה להתיחס.</p>","notation":[]},"39082":{"h":"יַחֵס","r":"KRU08599","alt":[],"source":"krupnik","glosses":[{"text":"to nobilize","label":""}],"html":"<p>1) הרים למעמד גבוה to nobilize  תרג׳ יב״ע במ׳ כ״ה י״ג: הא אנא מיחסיניה לכהונתא רבתא. 2) עי׳ יִחֵס. מגי׳ י״ב ע״ב: אי ליחוסא קאתי ליחסיה וליזיל עד בנימין. אִתְיַחֵס אתפ׳, עי׳ הִתְיַחֵס. תרג׳ יב״ע בר׳ כ״א י״ב: לא מתיחס בתרך. </p>","notation":["פַעל"]},"39083":{"h":"יַחַס","r":"KRU08600","alt":["יַחֲסוּתָא"],"source":"krupnik","glosses":[{"text":"legal pedigree","label":""}],"html":"<p>שייכות למשפחה כשרה legal pedigree  ירוש׳ יבמ׳ פ״ב ד׳ ע״א: גויים יש להם יחסים וכו׳ אין להם יחסים; קיד׳ ע״א ע״ב: ייחוסא וכו׳ ביחסותא וכו׳.</p>","notation":["ז׳"]},"39084":{"h":"יחף","r":"KRU08601","alt":[],"source":"krupnik","glosses":[{"text":"to become sore (feet)","label":"הִתְיַחֵף התפ׳,"}],"html":"<p>הִתְיַחֵף התפ׳, נפצע to become sore (feet)  איכ״ר פתיחתא: הציעו לו טפטיות וכו׳ כדי שלא יתיחפו רגליהם אעפ״כ נתיחפו רגליהם.</p>","notation":["Source marks no qal form"]},"39085":{"h":"יְחַף","r":"KRU08602","alt":[],"source":"krupnik","glosses":[{"text":"to be rubbed","label":""}],"html":"<p>היה חפוף ומשוחק to be rubbed  תרג׳ דב׳ ח׳ ד׳: ומסנך לא יחיפו.</p>","notation":["פ״ע"]},"39086":{"h":"יַחֵף","r":"KRU08603","alt":[],"source":"krupnik","glosses":[{"text":"to be swollen","label":"פַעל,"}],"html":"<p>פַעל, היה תפוח to be swollen  תרג׳ יב״ע שם שם (ורגלך לא בצקה): וריגליכון לא הליכו מיחפין.</p>","notation":[]},"39087":{"h":"יַחַף","r":"KRU08604","alt":[],"source":"krupnik","glosses":[{"text":"footsoreness","label":"2"}],"html":"<p>1 עי׳ יִחוּף. ילק׳ יר׳ רס״ו: כדי שלא יבוא רגלך לידי יחף. \n2 כאב הרגלים footsoreness  מכש׳ פ״ג מ״ח: אם חשב שידוחו רגליה וכו׳ בשעת היחף והדיש.</p>","notation":[]},"39088":{"h":"יְטַב","r":"KRU08606","alt":[],"source":"krupnik","glosses":[{"text":"to be good","label":""},{"text":"to do good","label":""}],"html":"<p>היה טוב to be good  תרג׳ דב׳ ו׳ כ״ד (לטוב לנו): למיטב לנא. אוֹטִיב, אֵיטִיב  אפ׳, עשה טובה to do good  תרג׳ בר׳ ל״ב י׳ (ואיטיבה עמך): ואוטיב עמך; ירמ׳ י׳ ה׳ (היטיב אין אותם): לאיטבא לית אינון ידעין. </p>","notation":["פ״ע"]},"39089":{"h":"יְטוּר","r":"KRU08608","alt":["יְטוּרָא"],"source":"krupnik","glosses":[{"text":"pillar of smoke","label":""}],"html":"<p>עמוד העשן pillar of smoke  תרג׳ יואל ג׳ ג׳ (ותימרות עשן): יטורין דתנן.</p>","notation":[]},"39090":{"h":"יַטֵּי","r":"KRU08609","alt":[],"source":"krupnik","glosses":[{"text":"to adduce","label":""}],"html":"<p>הביא, הכניס to adduce  ירוש׳ ברכ׳ פ״ב ד׳ ע״ב: לית אפשר דלא יטי מילה.</p>","notation":["פעל"]},"39091":{"h":"יֳי","r":"KRU08612","alt":[],"source":"krupnik","glosses":[{"text":"abbreviation of the Tetragrammaton","label":"1"},{"text":"interjection","label":"2"}],"html":"<p>1 קיצור שם הויה abbreviation of the Tetragrammaton  תרג׳ תה׳ ס״ט ט׳ (חסין יה): הסינא יי.\n2 מלת הקריאה interjection  תרג׳ מש׳ ד׳ ד׳ (יתמך דברי לבך): יי יקמט מליי לבך.</p>","notation":[]},"39092":{"h":"יֳיא","r":"KRU08613","alt":[],"source":"krupnik","glosses":[{"text":"woe!","label":""}],"html":"<p>אוי ואבוי woe!  תרג׳ יב״ע במ׳ כ״א ב״ט: ייא לבון סנאי צדיקיא.</p>","notation":["מה״ק"]},"39093":{"h":"יָיָא","r":"KRU08614","alt":[],"source":"krupnik","glosses":[{"text":"fair","label":""}],"html":"<p>יפה, טוב fair  תרג׳ ירוש׳ בר׳ כ״ט י״ז (יפת מראה): ייא בריווא.</p>","notation":["ת׳"]},"39094":{"h":"יֵיא","r":"KRU08615","alt":["לְיֵיא"],"source":"krupnik","glosses":[{"text":"whither?","label":""}],"html":"<p>לאן whither?  ברכ׳ נ״ח ע״ב: כגני לייא. ועי׳ כְּלַפֵּי לְיֵיא.</p>","notation":[]},"39095":{"h":"יֵיבָא","r":"KRU08619","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":"2"},{"text":"tie","label":"3"}],"html":"<p>1 עי׳ יֵבָא. ירוש׳ מג׳ פ״ב ע״ג ע״ב: ייבא כהיא דאמר ר׳ פלוני. \n2 שם אמורא name of an Amora  גיט׳ ס״ב ע״א: אמר רב ייבא.\n3 מין קשור tie  ב״ב קמ״ו ע״א: תרגם רב פפא כייבא וסבכתא.</p>","notation":[]},"39096":{"h":"יִיבּוּם","r":"KRU08620","alt":[],"source":"krupnik","glosses":[{"text":"levirate marriage","label":""}],"html":"<p>חובת נשיאת אשת האח המת levirate marriage  יבמ׳ ל״ט ע״ב: מצות ייבום קודמת למצות חליצה.</p>","notation":["ז׳"]},"39097":{"h":"יִיחוּל","r":"KRU08623","alt":[],"source":"krupnik","glosses":[{"text":"hope","label":""}],"html":"<p>תקוה hope  ברכ׳ ט״ז ע״ב: ונשכים ונמצא ייחול לבבינו.</p>","notation":["ז׳"]},"39098":{"h":"יָילָא","r":"KRU08627","alt":[],"source":"krupnik","glosses":[{"text":"hedge-hog","label":""}],"html":"<p>קפוד hedge-hog  ב״ב ד׳ ע״א: כלילא דיילי.</p>","notation":["ז׳"]},"39099":{"h":"יֵימַר","r":"KRU08628","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  חול׳ נ״ו ע״ב: רב יימר.</p>","notation":[]},"39100":{"h":"יָינוּבְרִיס","r":"KRU08629","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ ע״ז פ״א ל״ט ע״ג: הוה תמן חד גבר סב והוה שמיה יינובריס. </p>","notation":["שם איש"]},"39101":{"h":"יִינוֹמְלִים","r":"KRU08630","alt":["יִינוֹמְלִין"],"source":"krupnik","glosses":[{"text":"wine mixed with honey","label":""}],"html":"<p>יין מהול בדבש wine mixed with honey  תר׳ פי״א מ״א: עושין את היין יינומלים; שבת קל״ט ע״ב: ינומלין.</p>","notation":[]},"39102":{"h":"יִינוּן","r":"KRU08631","alt":[],"source":"krupnik","glosses":[{"text":"those","label":""}],"html":"<p>הללו those  ירוש׳ פאה פ״ז כ׳ ע״ב: ההוא דובשא דיהבית לכון דצליין יינון.</p>","notation":["מה״ג"]},"39103":{"h":"יַיס","r":"KRU08632","alt":[],"source":"krupnik","glosses":[{"text":"health","label":""}],"html":"<p>בריאות health  ירוש׳ בר׳ פ״ו י׳ ע״ד: אסור למימר ליה ייס.</p>","notation":["ז׳"]},"39104":{"h":"יִיסִי","r":"KRU08634","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ כלא׳ פ״ח ל״א ע״ג: ייסי ערקי בר נש דטור וכו׳. </p>","notation":["שם איש"]},"39105":{"h":"יירינוֹן","r":"KRU08636","alt":[],"source":"krupnik","glosses":[{"text":"rose-oil","label":""}],"html":"<p>שמן וורדים rose-oil  ירוש׳ דמ׳ פ״א כ״ב ע״ב: שמן וורד – ויירינון.</p>","notation":["ז׳","Source emendation: וַרְדִּינוֹן"]},"39106":{"h":"יִישַׁר כֹּחֲךָ","r":"KRU08639","alt":[],"source":"krupnik","glosses":[{"text":"a phrase of approval and thanks (may thy strength be firm)","label":""}],"html":"<p>נוסח של ברכת תודה a phrase of approval and thanks (may thy strength be firm)  יישר כחך שהצלתנו מידי הרועים.</p>","notation":[]},"39107":{"h":"יָכוֹל","r":"KRU08642","alt":[],"source":"krupnik","glosses":[{"text":"you might think, conclude","label":""},{"text":"as it were","label":""}],"html":"<p>שמא תאמר you might think, conclude  תוס׳ בר׳ ג׳ ח׳: יכול יתפלל אדם כל היום כולו פירש דניאל וזימנין תלתא ביומא וכו׳. כִּבְיָכוֹל, כאילו as it were  מכיל׳ בא פי״ד: וכשעתידין לחזור כביכול שכינה עמהם. </p>","notation":[]},"39108":{"h":"יְכוֹלְנִי","r":"KRU08643","alt":[],"source":"krupnik","glosses":[{"text":"I can","label":""}],"html":"<p>יכול אני I can  יומא ס״ז ע״א: אם ע״י עירוב יכולני לעשות אפילו שתי סוכות.</p>","notation":[]},"39109":{"h":"יכולני","r":"KRU08644","alt":[],"source":"krupnik","glosses":[{"text":"Joviani, a cohort of pretorians","label":""}],"html":"<p>אחד מלגיונות הרומאים Joviani, a cohort of pretorians  אסת״ר א׳ ג׳: יכולני וברקוריִאני.</p>","notation":["ז״ר","Source emendation: יוֹבְיָינֵי"]},"39110":{"h":"יְכוּלְתָּא","r":"KRU08645","alt":[],"source":"krupnik","glosses":[{"text":"power, ability","label":""}],"html":"<p>יכולת power, ability  תרג׳ דהי״ב כ׳ ו׳: לית יכולתא לכל מלכיא.</p>","notation":["נ׳"]},"39111":{"h":"יָכֹל","r":"KRU08646","alt":[],"source":"krupnik","glosses":[{"text":"to be allowed","label":""}],"html":"<p>היה רשאיֹ to be allowed  גיט׳ פ״ד מ״ה: לישא שפחה אינו יכול שכבר חציו בן חורין בת חורין אינו יכול שכבר חציו עבד.</p>","notation":["Marked biblical in source"]},"39112":{"h":"יָלַד","r":"KRU08652","alt":[],"source":"krupnik","glosses":[{"text":"to appear again (the moon)","label":"נוֹלַד נפ׳ 1"},{"text":"to originate","label":"נוֹלַד נפ׳ 2"},{"text":"to bear","label":"יְלֵד"},{"text":"to act as midwife","label":"יַלֵּד פַעל 2"},{"text":"to produce","label":"אוֹלֵד אפ׳, 2"},{"text":"to be born","label":"אִתְיַלֵּד, אִתְיְלִיד אתפ׳, 1"},{"text":"to grow populous","label":"אִתְיַלֵּד, אִתְיְלִיד אתפ׳, 2"}],"html":"<p>נוֹלַד נפ׳ 1 נראה׳ נתגלה׳ ביחוד הירח to appear again (the moon)  ר״ה כ׳ ע״ב: נולד קודם חצות וכו׳.\nנוֹלַד נפ׳ 2 נתהוה to originate  אבות פ״ב מ״ט: הרואה את הנולד.\nיְלֵד ילדה האשה. המליטה to bear  תרג׳ בר׳ כ״ט ל״ב (ותלד בן): וילידת בר.\nיַלֵּד פַעל 1 כנ״ל. תרג׳ תה׳ קמ״ד י״ג (צאננו מאליפות): ענאנא מילדן אלפיא. \nיַלֵּד פַעל 2 עזר בלידה to act as midwife  תרג׳ ירוש׳ שמ׳ א׳ ט״ו (המילדות): מילדתא.\nאוֹלֵד אפ׳, 1 כנ״ל 2. תרג׳ שמ׳ א׳ ט״ז (בילדכן): כד תהוין מולדן. \nאוֹלֵד אפ׳, 2 הוליד, גרם to produce  ק״ד ע״א: דקמוליד קלא וכל אולודי קלא וכו׳.\nאִתְיַלֵּד, אִתְיְלִיד אתפ׳, 1 נולד to be born  ביצה ב׳ ע״ב: כל ביצה דמתילדא האידנא.\nאִתְיַלֵּד, אִתְיְלִיד אתפ׳, 2 פרה ורבה to grow populous  תרג׳ יב״ע שמות א׳ ז׳ (וירבו): אתילידו.</p>","notation":["Marked biblical in source"]},"39113":{"h":"יַלְדָּה","r":"KRU08653","alt":[],"source":"krupnik","glosses":[{"text":"a young plant","label":""}],"html":"<p>צמח רך a young plant  נדר׳ נ״ז ע״ב: ילדה שסבכה בזקנה ובה פירות.</p>","notation":["Marked biblical in source"]},"39114":{"h":"יַלְדּוּתָא","r":"KRU08654","alt":[],"source":"krupnik","glosses":[{"text":"young","label":""}],"html":"<p>בחרות young  ב״מ מ״ד ע״א: בילדותיה מאי סבר ובזקנותיה מאי סבר.</p>","notation":["נ׳"]},"39115":{"h":"יַלָּדוּתָא","r":"KRU08655","alt":[],"source":"krupnik","glosses":[{"text":"family","label":""}],"html":"<p>מולדת, משפחה family  תרג׳ בר׳ כ״ד ד׳ (למולדתי תלך): לילדותי תיזיל.</p>","notation":["נ׳"]},"39116":{"h":"ילדיתא","r":"KRU08656","alt":[],"source":"krupnik","glosses":[{"text":"a woman in confinement","label":""}],"html":"<p>יולדת a woman in confinement  איכ״ר א׳ א׳ (חד מאתונא ו׳): ירחי ביטנתא דילדיתא.</p>","notation":["נ׳","Source emendation: יָלֵידְתָּא"]},"39117":{"h":"יְלַדְתָּא","r":"KRU08657","alt":[],"source":"krupnik","glosses":[{"text":"midwife","label":""}],"html":"<p>מילדת midwife  תרג׳ ירוש׳ שמ׳ א׳ י״ט (המילדות): ילדתי·</p>","notation":["נ׳"]},"39118":{"h":"יְלִילָא","r":"KRU08658","alt":[],"source":"krupnik","glosses":[{"text":"spy","label":""}],"html":"<p>מרגל spy  תרג׳ ירוש׳ במ׳ כ״א א׳ (המרגלים): ילילא.</p>","notation":["ז׳"]},"39119":{"h":"יִלֵּין","r":"KRU08659","alt":[],"source":"krupnik","glosses":[{"text":"these","label":""}],"html":"<p>מ״ג, אלה these  ירוש׳ ב״ב פ״ח ט״ז ע״ב: וילין וכו׳.</p>","notation":[]},"39120":{"h":"יִלֵּל","r":"KRU08660","alt":[],"source":"krupnik","glosses":[{"text":"to howl","label":"פיעל, 1"},{"text":"to search through","label":"פיעל, 2"}],"html":"<p>פיעל, 1 צווח וגעה to howl  ב״ר פי״ט: התחילה מייללת עליו בקולה.\nפיעל, 2 חקר to search through  שהש״ר א׳ י׳ : בשעה שמיללין ההלכה אלו עם אלו.</p>","notation":[]},"39121":{"h":"יַלֵּל","r":"KRU08661","alt":[],"source":"krupnik","glosses":[{"text":"to espy","label":"פַעל,"}],"html":"<p>פַעל, תר וריגל to espy  ירוש׳ תענ׳ פ״ד ס״ד ע״ד: הוון מייללין קרתא.</p>","notation":[]},"39122":{"h":"יְלָלָא","r":"KRU08662","alt":["יְלַלְתָּא"],"source":"krupnik","glosses":[{"text":"howling","label":""}],"html":"<p>זעקה ויללה howling  תרג׳ צפ׳ א׳ י׳ (ויללה): ויללא; ירמ׳ כ״ה ל״ו (ויללת אדירי הצאן): ויללת תקיפי עמא.</p>","notation":[]},"39123":{"h":"יְלֵף","r":"KRU08664","alt":[],"source":"krupnik","glosses":[{"text":"to learn","label":""}],"html":"<p>למד to learn  תרג׳ מש׳ ל׳ ג׳ (ולא למדתי חכמה): ולא יליפית חכמתא.</p>","notation":["פ״ע"]},"39124":{"h":"יַלֵּף","r":"KRU08665","alt":[],"source":"krupnik","glosses":[{"text":"to teach","label":"פַעל, אפ׳,"}],"html":"<p>פַעל, אפ׳, אוֹלֵף לימד to teach  ירוש׳ חג׳ פ״ב ע״ח ע״א: מילף ומילפה; שבי׳ פ״ה ל״ו ע״א: ולא בן אולפן רבי.</p>","notation":[]},"39125":{"h":"יַלְתָּא","r":"KRU08669","alt":[],"source":"krupnik","glosses":[{"text":"a woman’s name","label":""}],"html":"<p>שם אשה a woman’s name  גיט׳ ס״ז ע״ב: שמעה ילתא.</p>","notation":[]},"39126":{"h":"יָם","r":"KRU08671","alt":[],"source":"krupnik","glosses":[{"text":"tank, the receptacle in the wine or oil press","label":"1"}],"html":"<p>1 בית קבול ביקב tank, the receptacle in the wine or oil press  ב״ב פ״ד מ״ה: המוכר את בית הבד מכר את הים ואת הממל.\n2 עי׳ יַם נָפָה. זבים פ״ד מ״ב: על התנור ועל הים וכו׳. </p>","notation":[]},"39127":{"h":"יָם אוֹקְיָינוֹס","r":"KRU08672","alt":[],"source":"krupnik","glosses":[{"text":"the Mediterranean Sea","label":""}],"html":"<p>ים התיכון the Mediterranean Sea  גיט׳ ח׳ ע״א: מקפלוריא ועד ים אוקיינוס ומנחל מצרים ועד ים אוקיינוס מן החוט ולפנים ארץ ישראל וכו׳.</p>","notation":[]},"39128":{"h":"יַם נָפָה","r":"KRU08674","alt":[],"source":"krupnik","glosses":[{"text":"the receiver of flour at sifting","label":""}],"html":"<p>קרקעית הנפה והכברה the receiver of flour at sifting  בל׳ פט״ו מ״ג: ים נפה של סילתין טמא ושל בעלי בתים טהור.</p>","notation":[]},"39129":{"h":"יַמָּה שֶׁל חֵיִלַת","r":"KRU08675","alt":[],"source":"krupnik","glosses":[{"text":"the Lake of Antiochia","label":""}],"html":"<p>אגם מים בסוריא הצפונית the Lake of Antiochia  ב״ב ע״ד ע״ב: אלו הן שבע ימים וארבע נהרות שמקיפין את ארץ ישראל וכו׳ ימה של חילת וכו׳.</p>","notation":[]},"39130":{"h":"יָם שֶל טִבֵרִיָּא","r":"KRU08676","alt":["יַמָּה שֶׁל טִבֵרִיָּא"],"source":"krupnik","glosses":[{"text":"Lake of Tiberias","label":""}],"html":"<p>ים כנִרת Lake of Tiberias  ב״ר פצ״ח: כל חוף ים של טבריא נקרא כנרת; ב״ב ע״ד ע״ב: אלו הן שבע ימים וכו׳ ימה של טבריא.</p>","notation":[]},"39131":{"h":"יַמָּה שֶל יָפוֹ","r":"KRU08677","alt":[],"source":"krupnik","glosses":[{"text":"the Mediterranean Sea","label":""}],"html":"<p>ים התיכון the Mediterranean Sea  ספרי דב׳ ל״ג י״ט: כי שפע ימים יינקו זו ימה של יפו.</p>","notation":[]},"39132":{"h":"יַמָּה שֶׁל סְדוֹם","r":"KRU08678","alt":[],"source":"krupnik","glosses":[{"text":"the Dead Sea","label":""}],"html":"<p>ים המלח the Dead Sea  ב״ב ע״ד ע״ב: ימה של טבריא וימה של סדום.</p>","notation":[]},"39133":{"h":"יַמָּה שֶׁל סִיבְבֵי","r":"KRU08679","alt":["יַמָּה שֶׁל סוֹפְנֵי","יַמָּה שֶׁל סַמְבוּ"],"source":"krupnik","glosses":[{"text":"Samachonitis","label":""}],"html":"<p>אגם מים מצפון לים כנרת Samachonitis  ב״ב ע״ד ע״ב: ימה של חילת וכו׳ וימה של סיבכי; ירוש׳ שם פ״ה ט״ו ע״א: ימה של סמכו; תוס׳ ב״ק ח׳ י״ח: ים ודרום ירשה וכו׳ זה ימה של סופני דרום זה ימה של טבריא.</p>","notation":[]},"39134":{"h":"יַמָּא","r":"KRU08681","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Palestine","label":""}],"html":"<p>בארץ ישראל name of a place in Palestine  ירוש׳ גיט׳ פ״ו מ״ח ע״א: מן ימא לטיגני.</p>","notation":["שם מקום"]},"39135":{"h":"יַמָּא דַחֲמָץ","r":"KRU08683","alt":[],"source":"krupnik","glosses":[{"text":"Lake of Hums in Syria","label":""}],"html":"<p>אגם מים בסוריא סמוך לעיר חמץ Lake of Hums in Syria  ירוש׳ כלא׳ פ״ט ל״ב ע״ג: ימא דחמץ.</p>","notation":[]},"39136":{"h":"יַמָּא דְטִיבֵרִיָּא","r":"KRU08684","alt":[],"source":"krupnik","glosses":[{"text":"Lake of Tiberias","label":""}],"html":"<p>ים כנרת Lake of Tiberias  ירוש׳ ע״ז פ״ב ה״ט: והא ימא דטיבריא בגון המים המהלכין הם.</p>","notation":[]},"39137":{"h":"יַמָּא דְמִילְחָא","r":"KRU08686","alt":["יַמָּא דְמֵישְׁרָא","יַמָּא דִסְדוֹם"],"source":"krupnik","glosses":[{"text":"the Dead Sea","label":""}],"html":"<p>ים המלח the Dead Sea  ירוש׳ כלא׳ פ״ט ל״ב ע״ג: ימא דמילחא; שבת ק״ח ע״ב: אפי׳ גברא דטבע בכל מימות שבעולם בימא דסדום לא טבע; תרג׳ יב״ע דב׳ ג׳ י״ז (ים הערבה): ימא דמישרא.</p>","notation":[]},"39138":{"h":"יַמְבְּרִיס","r":"KRU08688","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  תרג׳ יב״ע שמ׳ א׳ ט״ו: יניס וימבריס רישי חרשיא. </p>","notation":["שם איש"]},"39139":{"h":"יַמָּה","r":"KRU08690","alt":[],"source":"krupnik","glosses":[{"text":"sea","label":""}],"html":"<p>ים sea  ירוש׳ שקל׳ פ״ה מ״ה ע״ד: לימתי וכו׳ בימה סכנת.</p>","notation":["נ׳"]},"39140":{"h":"יְמֵי","r":"KRU08692","alt":[],"source":"krupnik","glosses":[{"text":"to swear","label":""},{"text":"to cause to swear","label":""}],"html":"<p>נשבע to swear  תרג׳ שמ׳ כ׳ ז׳: לא תימי בשמא. אוֹמִי אפ׳ 1) כנ״ל. תרג׳ שופ׳ י״ז ב׳ (ואת אלית): את אומית. 2) השביע to cause to swear  תרג׳ מל״א ח׳ ל״א (להאלותו): לאומיותיה. </p>","notation":["פ״י"]},"39141":{"h":"יֵמָם","r":"KRU08694","alt":[],"source":"krupnik","glosses":[{"text":"by day","label":""}],"html":"<p>יומם by day  תרג׳ יר׳ י״ד י״ז (לילה ויומם): לילי וימם.</p>","notation":["תה״פ"]},"39142":{"h":"יְמָמָא","r":"KRU08695","alt":[],"source":"krupnik","glosses":[{"text":"day, day-time","label":"1"},{"text":"day-light","label":"2"}],"html":"<p>1 יום, שעות היום day, day-time  יומא ע״ד ע״ב: מאן דאית ליה סעודתא לא ליכלה אלא ביממא.\n2 אור היום day-light  בר׳ ג׳ ע״א: למה לי סימנא יממא הוא.</p>","notation":["ז׳"]},"39143":{"h":"יממיא","r":"KRU08696","alt":[],"source":"krupnik","glosses":[{"text":"a word in a charm formula","label":""}],"html":"<p>תיבה בנוסח של שבועה a word in a charm formula  תוס׳ שבת צוק׳ ז׳ (ח׳), א׳: יממיא ובוציא.</p>","notation":[]},"39144":{"h":"ימן","r":"KRU08698","alt":[],"source":"krupnik","glosses":[{"text":"to believe","label":"אפ׳,"}],"html":"<p>אפ׳, הֵימֵן האמין to believe  ירוש׳ חג׳ פ״ב ע״ז ע״ד: אי הימנך הא טבאות.</p>","notation":["Source marks no qal form"]},"39145":{"h":"ימס","r":"KRU08699","alt":[],"source":"krupnik","glosses":[{"text":"to melt","label":"אִתְיְמַס אתפ׳,"}],"html":"<p>אִתְיְמַס אתפ׳, נמס to melt  תרג׳ יש׳ ל״ד ג׳ (ונמסו הרים): ויתימסון טוריא.</p>","notation":["Source marks no qal form"]},"39146":{"h":"יַמְרִיס","r":"KRU08701","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  תרג׳ יב״ע במ׳ כ״ב כ״ב: ותרין עולימוי יניס וימריס עמיה. </p>","notation":["שם איש"]},"39147":{"h":"יַנַּאי","r":"KRU08703","alt":[],"source":"krupnik","glosses":[{"text":"John Hyrcan, King of Judaea","label":""}],"html":"<p>מלך יהודה (יוחנן הורקנוס) John Hyrcan, King of Judaea  בר׳ כ״ט ע״א: הוא ינאי הוא יוחנן.</p>","notation":[]},"39148":{"h":"יִנוּן","r":"KRU08704","alt":[],"source":"krupnik","glosses":[{"text":"those","label":""}],"html":"<p>הללו those  רוש׳ בר׳ פ״א ג׳ ע״ד: וינון מחמרין.</p>","notation":["מה״ג"]},"39149":{"h":"יָנוּקָא","r":"KRU08705","alt":[],"source":"krupnik","glosses":[{"text":"child","label":"1"},{"text":"a man’s name","label":"2"}],"html":"<p>1 ילד child  סוכה נ״ו ע״ב: שותא דינוקא בשוקא או דאבוהי או דאימיה.\n2 שם איש a man’s name  ב״ב ז׳ ע״ב: מר ינוקא וכו׳ בריה דרב חסדא.</p>","notation":["ז׳"]},"39150":{"h":"יָנוּקְתָּא","r":"KRU08706","alt":[],"source":"krupnik","glosses":[{"text":"maiden","label":""}],"html":"<p>נערה maiden  ב״ב ג׳ ע״ב: כי חזית ההיא ינוקתא דקא בעי למנסבה.</p>","notation":["נ׳"]},"39151":{"h":"ינח","r":"KRU08707","alt":[],"source":"krupnik","glosses":[{"text":"to set down","label":"אַנַּח אפ׳,"},{"text":"to lie","label":"אִתְנַח אתפ׳,"}],"html":"<p>אַנַּח אפ׳, הניח to set down  שבת ו׳ ע״א: כי מנח ליה.\nאִתְנַח אתפ׳, היה מונח to lie  חול׳ מ״ה ע״א: מתנח ביה מוחא.</p>","notation":["Source marks no qal form"]},"39152":{"h":"יני","r":"KRU08708","alt":[],"source":"krupnik","glosses":[{"text":"to overreach","label":"אפ׳, אוֹנִי 1"},{"text":"to alienate","label":"אפ׳, אוֹנִי 2"}],"html":"<p>אפ׳, אוֹנִי 1 הונה ורמה to overreach  תרג׳ יב״ע ויק׳ כ״ה י״ד: לאוניא.\nאפ׳, אוֹנִי 2 הניא, הסיר to alienate  תרג׳ במ׳ ל״ב ט׳ (ויניאו): ואוניאו.</p>","notation":["Source marks no qal form"]},"39153":{"h":"יַנַּיי","r":"KRU08709","alt":[],"source":"krupnik","glosses":[{"text":"name of Amoraim","label":""}],"html":"<p>שם אמוראים name of Amoraim  ירוש׳ תענ׳ פ״ד ס״ח ע״א: ר׳ יניי מן דעלי.</p>","notation":[]},"39154":{"h":"יַנִּיס","r":"KRU08711","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  תרג׳ יב״ע ויק׳ כ״ב כ״ב: ותרין עולימוי יניס וימבריס עמיה. </p>","notation":["שם איש"]},"39155":{"h":"יַנִּיק","r":"KRU08712","alt":[],"source":"krupnik","glosses":[{"text":"suckling","label":"1"},{"text":"young man","label":"2"},{"text":"twig","label":"3"}],"html":"<p>1 יונק suckling  תרג׳ ש״א ט״ו ג׳ (מעולל ועד יונק): מעולים ועד יניק.\n2 נער young man  קיד׳ ל״ב ע״ב: יניק וחכים.\n3 ענף twig  תרג׳ תה׳ פ׳ י״ב (יונקותיה): יניקהא.</p>","notation":["ז׳"]},"39156":{"h":"יִנֵּן","r":"KRU08713","alt":[],"source":"krupnik","glosses":[{"text":"to awaken","label":"פיעל,"}],"html":"<p>פיעל, העיר, עורר to awaken  ילק׳ מלכ׳ ר׳: עתיד ליינן רשעי ארץ.</p>","notation":[]},"39157":{"h":"יְנַק","r":"KRU08715","alt":[],"source":"krupnik","glosses":[{"text":"to suck","label":""}],"html":"<p>ינק ומצץ to suck  בר׳ מ׳ ע״ב: מירבא רבו מארעא מינקי לא ינקי מארעא.</p>","notation":["פ״י"]},"39158":{"h":"יַנֵּק","r":"KRU08716","alt":[],"source":"krupnik","glosses":[{"text":"to give suck","label":"פַעל, אפ׳,"}],"html":"<p>פַעל, אפ׳, אוֹנִיק, אַיְינִיק היניק to give suck  תרג׳ ירוש׳ שמ׳ ט״ו ב׳: דהוה מינק לן דבש מן כיפא; ב״ר פצ״ח: יתברכון דדיא דהכין אוניקו; ירוש׳ כלא׳ פ״א כ״ז ע״ב: ליט ביזא דכן איינק.</p>","notation":[]},"39159":{"h":"ינְקָא","r":"KRU08717","alt":[],"source":"krupnik","glosses":[{"text":"suckling","label":"1"},{"text":"young camel","label":"2"}],"html":"<p>1 יונק suckling  במ״ר פ״ה: כהן ינקא דנפק ממעי דאימיה.\n2 גמל צעיר young camel  תרג׳ יר׳ ב׳ כ״ג (בכרה): ינקא.</p>","notation":["ז׳"]},"39160":{"h":"יַנְקוּתָא","r":"KRU08718","alt":[],"source":"krupnik","glosses":[{"text":"youth","label":""}],"html":"<p>בחרות youth  שבת קנ״ב ע״א: ינקותא כלילא דוורדא סבותא כלילא דחילפי.</p>","notation":["נ׳"]},"39161":{"h":"יַנְקָנָא","r":"KRU08719","alt":[],"source":"krupnik","glosses":[{"text":"young man","label":""}],"html":"<p>נער young man  תרג׳ יש׳ ג׳ ד׳ (ונתתי נערים שריהם): ואימני ינקניא פרנסיהון.</p>","notation":["ז׳"]},"39162":{"h":"יָסַד","r":"KRU08721","alt":[],"source":"krupnik","glosses":[{"text":"to be founded","label":"נתפ׳,"}],"html":"<p>נתפ׳, ·– נִתְיַסֵּד נוסד ונתבסס to be founded  תנח׳ בר׳ א׳: שהעולם לא נתיסד אלא על התורה.</p>","notation":[]},"39163":{"h":"יְסַד","r":"KRU08722","alt":[],"source":"krupnik","glosses":[{"text":"to found","label":"יַסֵּד פעל"},{"text":"to be fastened, founded","label":"אִתְיַסַּד אתפ׳ 1"},{"text":"to be composed","label":"אִתְיַסַּד אתפ׳ 2"},{"text":"to be piled up","label":"אִתּוֹסַד אתפ׳"}],"html":"<p>יַסֵּד פעל ביסס ובנה to found  תרג׳ תה׳ פ״ט י״ב (אתה יסדתם): אנת יסדתנון; שם ק״ד ה׳ (יסד ארץ על מכוניה): מייסד ארעא על בסיסה.\nאִתְיַסַּד אתפ׳ 1 נתחזק to be fastened, founded  תרג׳ איוב מ״א ט״ו (יצוק עליו בל ימוט): יתייסד עליו דלא תזוע.\nאִתְיַסַּד אתפ׳ 2 נתחבר to be composed  תרג׳ תה׳ פ״ז א׳: דמתייסד על פום אבהתנא.\nאִתּוֹסַד אתפ׳ נגדש to be piled up  תרג׳ דהי״ב ל״א ז׳ (החלו הערמות ליסוד): שריאו כירוון לאתוסדא.</p>","notation":["פ״י"]},"39164":{"h":"יִסּוּד","r":"KRU08723","alt":[],"source":"krupnik","glosses":[{"text":"institution, establishment","label":""}],"html":"<p>תקון וקביעה institution, establishment  מנח׳ צ״ט ע״ב: פעמים שביטולה של תורה זהו יסודה.</p>","notation":["ז׳"]},"39165":{"h":"יִסּוּר","r":"KRU08725","alt":[],"source":"krupnik","glosses":[{"text":"punishment","label":""}],"html":"<p>עונש punishment  סנה׳ מ״ה ע״א: אין לך יסור גדול מזה.</p>","notation":["ז׳"]},"39166":{"h":"יְסוּרִים","r":"KRU08726","alt":["יְסוּרִין"],"source":"krupnik","glosses":[{"text":"suffering, trials","label":""}],"html":"<p>צער ומכאוב suffering, trials  בר׳ י׳ ע״א: הביא יסורים על חזקיהו ואמר לו לישעיהו לך ובקר את החולה; קדוש׳ פ״ב ע״א: לידי זקנה או לידי יסורין.</p>","notation":[]},"39167":{"h":"יסטיבס","r":"KRU08727","alt":[],"source":"krupnik","glosses":[{"text":"straw-mattress","label":""}],"html":"<p>מצע תבן straw-mattress  תוס׳ צוק׳ שבת י״ג (י״ד), ט״ו: לווחין של יסטיכס.</p>","notation":["ז׳","Source emendation: סְטִיכָס"]},"39168":{"h":"יַסֵּי חֳלִי","r":"KRU08728","alt":[],"source":"krupnik","glosses":[{"text":"a bitter herb","label":""}],"html":"<p>מין צמח מר a bitter herb  יר׳ פסח׳ פ״ב כ״ט ע״ג: חרחבינה – יסיחלי.</p>","notation":[]},"39169":{"h":"יַסְיָאן","r":"KRU08729","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ע״ז מ״ב ע״א: ר׳ יוסי בר יסיאן. </p>","notation":["שם איש"]},"39170":{"h":"יסם","r":"KRU08731","alt":[],"source":"krupnik","glosses":[{"text":"to become blind","label":"נִתְיַסֵּם נתפ׳,"}],"html":"<p>נִתְיַסֵּם נתפ׳, נסתמא, נתעוור to become blind  תנח׳ תולד׳ ז׳: כל מי שנתייסם בעיניו כאילו מת.</p>","notation":["Source marks no qal form"]},"39171":{"h":"יַסְמִין","r":"KRU08732","alt":[],"source":"krupnik","glosses":[{"text":"Jasmine flowers","label":""}],"html":"<p>מין פרח Jasmine flowers  שבת נ׳ ע״ב: כוספא דיסמין.</p>","notation":["ז׳"]},"39172":{"h":"יָסַף","r":"KRU08733","alt":[],"source":"krupnik","glosses":[{"text":"to increase","label":"הוֹסִף הפ׳"},{"text":"to be added","label":"נִתְוַסֵּף נתפ׳,"}],"html":"<p>הוֹסִף הפ׳ ·– נתרבה, קיבל יותר to increase  שבת ע״ז ע״ב: שלשה כל זמן שמזקינין מוסיפין גבורה ואלו הן דג ונחש וחזיר.\nנִתְוַסֵּף נתפ׳, נוסף, נתחבר ונצטרף to be added  פס׳ פ״ז ע״ב: לא הגלה הקב״ה את ישראל לבין האומות אלא כדי שיתוספו עליהם גרים.</p>","notation":["Source marks no qal form"]},"39173":{"h":"יְסַף","r":"KRU08734","alt":[],"source":"krupnik","glosses":[{"text":"to add","label":"אוֹסִיף אפ׳, 1"}],"html":"<p>אוֹסִיף אפ׳, 1 הרבה והוסיף to add  שבת קט״ז ע״ב: לא לאוספא על אורייתא דמשה קאתינא.\nאוֹסִיף אפ׳, 2 עי׳ הוֹסִיף. קיד׳ כ׳ ע״א: מוספא ואזלא. \nאִתּוֹסַף אתפּ׳ עי׳ נִתְוַסֵּף. בר׳ כ״ח ע״א: אתוספו כמה ספסלי. </p>","notation":["Source marks no qal form"]},"39174":{"h":"יָסַר","r":"KRU08735","alt":[],"source":"krupnik","glosses":[{"text":"to be punished","label":"נתפ׳,"}],"html":"<p>נתפ׳, ·– נִתְיַסֵּר נענש to be punished  ג׳ י׳: היו מתייסרין בחולי מעים.</p>","notation":[]},"39175":{"h":"יְסַד²","r":"KRU08736","alt":[],"source":"krupnik","glosses":[{"text":"to tie","label":""},{"text":"to forbid","label":""},{"text":"to be tried","label":""}],"html":"<p>1) חבש to tie  תרג׳ יש׳ ט״ו ג׳ (חגרו): יסרון. 2) אסר to forbid  יר׳ עיר׳ פ״ו כ״ג ע״ד: הוא ייסר. אִתְיַסַּר אתפ׳, נענש ביסורים to be tried  שהש״ר ב׳ ט״ז: ר׳ יוחנן אתייסר. </p>","notation":["פ״י"]},"39176":{"h":"יֳעא","r":"KRU08737","alt":[],"source":"krupnik","glosses":[{"text":"to bloom","label":""}],"html":"<p>פרח, הנץ to bloom  תרג׳ יב״ע במ׳ י״ז כ״ג (פרח): ייעא.</p>","notation":["פ״ע"]},"39177":{"h":"יַעְבֵּץ","r":"KRU08738","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ חג׳ פ״ב ע״ז ע״א: ר׳ חגיי בשם ר׳ יעבץ.</p>","notation":[]},"39178":{"h":"יָעַד","r":"KRU08739","alt":[],"source":"krupnik","glosses":[{"text":"to designate, esp. to designate a Hebrew handmaid as his wife","label":"פיעל,"}],"html":"<p>פיעל, ·– יִעֵד קבע ובחר; בחר האדון את שפחתו העברית לו לאשה to designate, esp. to designate a Hebrew handmaid as his wife  ירוש׳ קיד׳ פ״א נ״ט ע״ב: כיצד הוא מייעדה אומר לה בפני שנים הרי את מיועדת לי.</p>","notation":[]},"39179":{"h":"יְעַד","r":"KRU08740","alt":[],"source":"krupnik","glosses":[{"text":"to forewarn","label":""},{"text":"to be forewarned","label":""}],"html":"<p>1) כנ״ל. קיד׳ י״ח ע״ב: הא יעודי מייעד לה. 2) התרה והזהיר to forewarn  ב״ק כ״ד ע״א וע״ב: לייעורי תורא או לייעודי גברא. אִיָּעֵד אתפ׳, הוזהר to be forewarned  ב״ק ל״ז ע״ב לשווים הוא דאייעד למידי אחרינא לא. </p>","notation":["פ״י"]},"39180":{"h":"יעדוט","r":"KRU08741","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Palestine","label":""}],"html":"<p>בארץ ישראל name of a place in Palestine  ירוש׳ דמאי פ״ב כ״ב ע״ד: עיון ויעדוט.</p>","notation":["שם מקום","Source emendation: יַעְרוּט"]},"39181":{"h":"יִעוּד","r":"KRU08744","alt":[],"source":"krupnik","glosses":[{"text":"betrothal of a Hebrew handmaid to the owner","label":""}],"html":"<p>בחירת השפחה ע״י אדוניה לאשה betrothal of a Hebrew handmaid to the owner  קדוש׳ י״ח ע״ב: יעוד נישואין עושה או אירוסין עושה.</p>","notation":["ז׳"]},"39182":{"h":"יְעַט","r":"KRU08746","alt":[],"source":"krupnik","glosses":[{"text":"to counsel","label":""},{"text":"to take counsel","label":""}],"html":"<p>נתן עצה, יעץ to counsel  תרג׳ יב״ע בר׳ מ״ב כ״ד: שמעון דיעט למקטליה. אִתְיָעֵט אתפ׳, נמלך ונתיעץ to take counsel  תרג׳ יב״ע שמ׳ א׳ י׳ (הבה נתחכמה): נתיעט עליהון. </p>","notation":["פ״י"]},"39183":{"h":"יְעִידָה","r":"KRU08747","alt":[],"source":"krupnik","glosses":[{"text":"statement","label":"2"},{"text":"appointment","label":"3"}],"html":"<p>1 עי׳ יִעוּד. בכורות פ״א מ״ז: מצות יעידה קודמת למצות פדיה שנאמר אשר לא יעדה והפדה. \n2 עדות statement  ספרא פרק ח׳ פרשה ב׳: יעידת עד אחד יעידת שני עדים.\n3 התועדות ופגישה appointment  במ״ר פי״ד: ונועדתי לך לך היתה יעידה ולא היתה יעידה לכל ישראל.</p>","notation":["נ׳"]},"39184":{"h":"יָעֵף","r":"KRU08749","alt":[],"source":"krupnik","glosses":[{"text":"to annoy","label":"יִעֵף פיעל,"}],"html":"<p>יִעֵף פיעל, הציק to annoy  תנח׳ וירא כ״ב: אל תשגיח עליו שאינו בא אלא ליעף לנו.</p>","notation":["Marked biblical in source"]},"39185":{"h":"יָעַץ","r":"KRU08750","alt":[],"source":"krupnik","glosses":[{"text":"to consult","label":"יָעֵץ פיעל,"}],"html":"<p>יָעֵץ פיעל, נמלך ונועץ to consult  ילק׳ במ׳ תשפ״ה: שהיו מיעצים על ישראל.</p>","notation":["Marked biblical in source"]},"39186":{"h":"יעק","r":"KRU08751","alt":[],"source":"krupnik","glosses":[{"text":"to be troubled","label":"אִתְיֵעֵק אתפ׳,"}],"html":"<p>אִתְיֵעֵק אתפ׳, נמצא במצוק to be troubled  תרג׳ יב״ע שמ׳ א׳ י״ב (ויקוצו): ואתייעקו.</p>","notation":["Source marks no qal form"]},"39187":{"h":"יָפֶה","r":"KRU08752","alt":[],"source":"krupnik","glosses":[{"text":"good, healthy","label":"1"},{"text":"worth","label":"2"},{"text":"right, legal, valid","label":"3"},{"text":"quick, skilled","label":"4"},{"text":"undainty","label":"5"},{"text":"generous","label":"6"}],"html":"<p>1 משובח good, healthy  תרומ׳ פ״ב מ״ו: תורם מן היפה על הרע אבל לא מן הרע על היפה.\n2 שוה, ראוי, כדאי worth  כת׳ פ״ח מ״ג: שמין אותן כמה הן יפין בפירות וכמה הן יפין בלא פירות; ב״ק פ״ג מ״ט: ואין הנבילה יפה כלום.\n3 כשר, זכאי, מורשה right, legal, valid  יב׳ פ״י מ״ב: יפה כח בית דין וכו׳.\n4 זריז וחרוץ quick, skilled  פס׳ פ״ט ע״ב: שהיו ידיו של אחד מהן יפות.\n5 שאינו בחרן וקפדן undainty  חול׳ פ״ד מ״ז: השוחט את הבהמה ומצא בה שליא נפש היפה תאכלנה.\n6 נדבן generous  תר׳ פ״ד מ״ג: עין יפה אחת מארבעים וכו׳ והבינונית מחמשים והרעה מששים.</p>","notation":["Marked biblical in source"]},"39188":{"h":"יָפָה","r":"KRU08753","alt":[],"source":"krupnik","glosses":[{"text":"to improve","label":"יִפָּה פיעל 1"},{"text":"to give a prerogative","label":"יִפָּה פיעל 2"},{"text":"to become handsome","label":"נִתְיַפָּה נתפ׳, 1"},{"text":"to be praised","label":"נִתְיַפָּה נתפ׳, 2"}],"html":"<p>יִפָּה פיעל 1 תקן to improve  ירוש׳ שבת פ״ז י׳ ע״א: קצר לצורך עשבים חייב משום קוצר ואינו חייב משום מייפה את הקרקע.\nיִפָּה פיעל 2 מלא יד פלוני, הרשה וזיכה to give a prerogative  ב״ב נ״א ע״א: במתנה בקש ליתנו לו ולמה כתב לו בלשון מכר כדי לייפות כחו.\nנִתְיַפָּה נתפ׳, 1 נעשה יפה to become handsome  תענ׳ כ״ג ע״ב: אמר לה תתיפי הנה ונתייפת.\nנִתְיַפָּה נתפ׳, 2 היה מהולל to be praised  ב״ר פנ״ט: נתייפיתה בעליונים שנאמר וכו׳ נתייפיתה בתחתונים נשיא אלהים אתה בתוכנו.</p>","notation":["Source marks no qal form"]},"39189":{"h":"יִפּוּי","r":"KRU08754","alt":[],"source":"krupnik","glosses":[{"text":"prerogative","label":""}],"html":"<p>זכות יתירה prerogative  תנח׳ חיי א׳: אי זה היפוי שלי אני ובני נכנסין לעיר ואין בני אדם מכירין בין האב לבן.</p>","notation":["ז׳"]},"39190":{"h":"יְפַח","r":"KRU08755","alt":[],"source":"krupnik","glosses":[{"text":"breath","label":""}],"html":"<p>הבל הפה breath  סנה׳ י״ח ע״ב: אם קידום תקיף לחדא יהא יפח בלועך נפיק לקיבליה דין הוא אדר.</p>","notation":["ז׳"]},"39191":{"h":"יָפְיוּת","r":"KRU08756","alt":[],"source":"krupnik","glosses":[{"text":"beauty","label":""}],"html":"<p>יופי, נוי beauty  מגי׳ ט׳ ע״ב: יפיותו של יפת יהא באהלי שם.</p>","notation":["נ׳"]},"39192":{"h":"יְפֵיפֶה","r":"KRU08757","alt":[],"source":"krupnik","glosses":[{"text":"very nice, beautiful","label":""}],"html":"<p>נאה, יפה מאד very nice, beautiful  נדר׳ כ׳ ע״ב: מפני מה בניך יפיפין ביותר.</p>","notation":["ת׳"]},"39193":{"h":"יְפֵיפוּת","r":"KRU08758","alt":[],"source":"krupnik","glosses":[{"text":"beauty","label":""}],"html":"<p>נוי, יופי beauty  שהש״ר ד׳ ד׳: אני הוא שעשיתיו תל בעולם הזה ואני הוא שעתיד לעשותו יפיפות לעולם הבא.</p>","notation":["נ׳"]},"39194":{"h":"יְפֵיפִיָּה","r":"KRU08759","alt":[],"source":"krupnik","glosses":[{"text":"handsome woman","label":""}],"html":"<p>אשה נאה, יפת תואר handsome woman  תענ׳ ל״א ע״א: יפיפיות שבהן מה היו אומרות תנו עיניכם ליופי שאין האשה אלא ליופי.</p>","notation":["נ׳"]},"39195":{"h":"יָפְיָפְיָה","r":"KRU08760","alt":[],"source":"krupnik","glosses":[{"text":"name of an angel","label":""}],"html":"<p>שם מלאך name of an angel  תרג׳ יב״ע דב׳ ל״ד ו׳: רבני חכמתא וכו׳ יפיפיה.</p>","notation":[]},"39196":{"h":"יִפֵּךְ","r":"KRU08761","alt":[],"source":"krupnik","glosses":[{"text":"to turn over","label":"פיעל,"}],"html":"<p>פיעל, הפך to turn over  תוס׳ צוק׳ כלא׳ סוף א׳: שדה שעלו בה עשבים אין מחייבים אותו לייפך.</p>","notation":[]},"39197":{"h":"יפע","r":"KRU08762","alt":[],"source":"krupnik","glosses":[{"text":"to reveal","label":"הפ׳ הוֹפִיַע 1"},{"text":"to lift up","label":"הפ׳ הוֹפִיַע 2"},{"text":"to have the courage to rebuke","label":"הוֹפִיַע פָּנִים"}],"html":"<p>הפ׳ הוֹפִיַע 1 גילה to reveal  ב״ר פ״ד: צפונות מופיע.\nהפ׳ הוֹפִיַע 2 הרים to lift up  שמו״ר פ״א: פועה שהופיעה את ישראל לאלהים.\nהוֹפִיַע פָּנִים העיז פנים, התחצף to have the courage to rebuke  שמו״ר פ״א: שהופיעה פנים כנגד פרעה וזקפה חוטמו בו.</p>","notation":["Source marks no qal form"]},"39198":{"h":"יָצָא","r":"KRU08763","alt":[],"source":"krupnik","glosses":[{"text":"to be excluded","label":""},{"text":"to comply with the requirements of the law","label":""},{"text":"to be freed","label":""},{"text":"to be divorced","label":""},{"text":"to retire for human needs","label":""},{"text":"in a similar way, similar","label":""}],"html":"<p>1) היה מחוץ לכלל to be excluded  מכי׳ משפ׳ ב׳: בחלב אמו יצא עוף שאין לו חלב. 2) עשה חובתו to comply with the requirements of the law  בר׳ פ״ב מ״א: היה קורא בתורה והגיע זמן המקרא אם כיון לבו יצא. 3) נשתחרר to be freed  קיד׳ כ״ד ע״א: יוצא בשן וכו׳. 4) נתגרש to be divorced  כת׳ פ״ז מ״ו: ואלו יוצאות שלא בכתובה. 5) עשה את צרכיו to retire for human needs  בר׳ ס״ב ע״א: השכם וצא הערב וצא. כַּיּוֹצֵא בְ־ כדומה לדבר in a similar way, similar  פס׳ פ״ג מ״ב: אם יש כיוצא בו שהחמיץ; מו״ק ט״ז ע״ב: כיוצא בדבר אתה אומר. </p>","notation":["Marked biblical in source"]},"39199":{"h":"יָצָא יְדֵי־","r":"KRU08764","alt":[],"source":"krupnik","glosses":[{"text":"to be justified before, to do justice to","label":""}],"html":"<p>to be justified before, to do justice to  שק׳ פ״ג מ״ב: לצאת ידי הבריות וכו׳ לצאת ידי המקום; ב״מ פ״ז מ״א: לא יצאת ידי חובתך עמהן. </p>","notation":[]},"39200":{"h":"יָצָא מִן הַכְּלָל","r":"KRU08765","alt":[],"source":"krupnik","glosses":[{"text":"to be taken out of the general rule","label":""}],"html":"<p>יש בענין זה דין מיוחד to be taken out of the general rule  ספרא פתיחה: כל דבר שהיה בכלל ויצא מן הכלל וכו׳.</p>","notation":[]},"39201":{"h":"יָצָא נָקִי מִנְּכָסָיו","r":"KRU08766","alt":[],"source":"krupnik","glosses":[{"text":"to become poor","label":""}],"html":"<p>נתרושש to become poor  פס׳ כ״ב ע״ב: יצא פלוני נקי מנכסיו.</p>","notation":[]},"39202":{"h":"יָצָא שְׂכָרוֹ בְהֶפְסֵדוֹ","r":"KRU08767","alt":[],"source":"krupnik","glosses":[{"text":"benefit und disadvantage are counterbalanced","label":""},{"text":"to dismiss","label":""},{"text":"to claim","label":""},{"text":"to spend","label":""},{"text":"to present, to produce","label":""},{"text":"to act in another’s behalf","label":""},{"text":"to deduct","label":""},{"text":"to exclude","label":""},{"text":"to carry","label":""},{"text":"to discredit","label":""},{"text":"to the exclusion of, exclusively","label":""}],"html":"<p>אין השכר שוה בנזק benefit und disadvantage are counterbalanced  אבות פ״ה מי״א: יצא שכרו בהפסדו וכו׳ יצא הפסדו בשכרו. הוֹצִיא הפ׳ 1) גרש to dismiss  סוטה פ״ו מ״א: מי שקינא לאשתו וכו׳ יוציא ויתן כתובה. 2) תבע, בא בטענה to claim  ב״ק פ״ג מי״א: המוציא מחבירו עליו הראיה. 3) נתן והשקיע כסף to spend  שבת ק״נ ע״א: כך וכך דינרין הוצאתי על דירה זו. 4) הראה לבי״ד to present, to produce  כת׳ פ״ט מ״ט: בעל חוב שהוציא שט״ח ואין עמו פרוזבול. 5) פיטר את חבירו מחובתו to act in another’s behalf  ר״ה ל״ד ע״ב: למה שליח צבור יורד לפני התיבה וכו׳ כדי להוציא את שאינו בקי. 6) ניכה to deduct  ב״מ פ״ג מ״ז: אם היתה מדה מרובה אינו מוציא לו חסרונות. 7) לא מנה בכלל to exclude  ירוש׳ יבמ׳ פ״א ב׳ ע״ג: איילונית מטעם אחר הוצאתה. 8) נשא to carry  שבת פ״ז מ״ב: המוציא מרשות לרשות. הוֹצִיא לַעַז פרסם שם רע to discredit  שבת צ״ו ע״ב: אתה מוציא לעז על אותו צדיק. לְהוֹצִיא חוץ מן, למעט to the exclusion of, exclusively  קיד׳ ע״א ע״א: האזרח להוציא את הנשים. </p>","notation":[]},"39203":{"h":"יַצֵּב","r":"KRU08768","alt":[],"source":"krupnik","glosses":[{"text":"to establish","label":""}],"html":"<p>פַּעל, ביסס to establish  תרג׳ דהי״א ד׳ כ״ג: מיצבין יה עלמא.</p>","notation":[]},"39204":{"h":"יָצוּל","r":"KRU08771","alt":[],"source":"krupnik","glosses":[{"text":"the beam of a plough","label":""}],"html":"<p>כלונס שבמחרשה the beam of a plough  כל׳ פכ״א מ״ב: בחרב ובבורך וביצול.</p>","notation":["ז׳"]},"39205":{"h":"יְצוּר","r":"KRU08774","alt":[],"source":"krupnik","glosses":[{"text":"creature","label":""}],"html":"<p>בריה, נברא, יציר creature  ב״ר פ״ט: עד שלא נוצר יצור מחשבתו גלויה לפניך.</p>","notation":["ז׳"]},"39206":{"h":"יְצִיאָה","r":"KRU08776","alt":[],"source":"krupnik","glosses":[{"text":"going out","label":"1"},{"text":"discharge of the bowels","label":"2"},{"text":"expense","label":"3"},{"text":"way out","label":"4"},{"text":"divorce","label":"5"},{"text":"rise of the sun","label":"6"},{"text":"the carrying (on the Sabbath) of an object from private to public ground etc.","label":"7"}],"html":"<p>1 פעולת היוצא going out  בר׳ פ״ט מ״א: הנכנס לכרך מתפלל שתים אחת בכניסתו ואחת ביציאתו.\n2 עשית צרכים discharge of the bowels  בר׳ ס״ב ע״ב: שינה בעמוד השחר וכו׳ יציאה וכו׳.\n3 הוצאת כסף expense  ב״ק פ״ט מ״ד: ואם היציאה יתירה על השבח נותן לו את השבח.\n4 מוצא way out  מזוזה ב׳: אכסדרה שהיא לפנים מן הבתים ואין לה יציאה ממקום אחר.\n5 גירושין divorce  קדוש׳ ה׳ ע״א: אמר קרא ויצאה והיתה מקיש הויה ליציאה מה יציאה בשטר אף הויה נמי בשטר.\n6 זריחת השמש rise of the sun  ירוש׳ בר׳ פ״א ב׳ ע״ג: כתיב השמש יצא על הארץ וכו׳ מקיש יציאתו לביאתו.\n7 הוצאת דבר מרשות לרשות בשבת the carrying (on the Sabbath) of an object from private to public ground etc.  שבת פ״א מ״א: יציאות השבת שתים שהן ארבע וכו׳.</p>","notation":["נ׳"]},"39207":{"h":"יְצִיאַת מִצְרַיִם","r":"KRU08777","alt":[],"source":"krupnik","glosses":[{"text":"the exodus from Egypt","label":""}],"html":"<p>גאולת ישראל מגלות מצרים the exodus from Egypt  מכי׳ יתרו א׳: ששקולה יציאת מצרים כנגד כל הנסים.</p>","notation":[]},"39208":{"h":"יְצִיאַת נְשָׁמָה","r":"KRU08778","alt":[],"source":"krupnik","glosses":[{"text":"the separation of the soul from the body, death","label":""}],"html":"<p>פרידת הנשמה מן הגוף, מיתה the separation of the soul from the body, death  מו״ק כ״ה ע״א: העומד על המת בשעת יציאת נשמה חייב לקרוע.</p>","notation":[]},"39209":{"h":"יַצִּיבָא","r":"KRU08779","alt":[],"source":"krupnik","glosses":[{"text":"native, citizen","label":""}],"html":"<p>אזרח, יהודי מלידה ומבטן native, citizen  תרג׳ יב״ע ויק׳ ט״ז כ״ט (האזרח והגר): יציבא וגיורא.</p>","notation":["Marked biblical in source"]},"39210":{"h":"יְצִיבָה","r":"KRU08780","alt":[],"source":"krupnik","glosses":[{"text":"prophecy","label":""}],"html":"<p>התנבאות prophecy  מכי׳ בשלח שירה י׳: אין יציבה אלא נבואה.</p>","notation":["נ׳"]},"39211":{"h":"יָצִיעַ","r":"KRU08782","alt":[],"source":"krupnik","glosses":[{"text":"wing of a building","label":""}],"html":"<p>בנין קטן נוסף לבית wing of a building  ב״ב פ״ד מ״א: המוכר את הבית לא מכר את היציע.</p>","notation":["Marked biblical in source"]},"39212":{"h":"יְצִיקָה","r":"KRU08783","alt":[],"source":"krupnik","glosses":[{"text":"pouring","label":"1"},{"text":"casting (metal)","label":"2"}],"html":"<p>1 שפיכה pouring  ירוש׳ נזיר פ״ה נ״ג ע״ד: ויצקת משמן מנחה לרבות המנחות ליציקה.\n2 התכה casting (metal)  ירוש׳ בר׳ פ״א ב׳ ע״ד: בכל שעה ושעה הן נראין כשעת יציקתן.</p>","notation":["נ׳"]},"39213":{"h":"יְצִירָה","r":"KRU08785","alt":[],"source":"krupnik","glosses":[{"text":"creation","label":"1"},{"text":"pottery","label":"2"}],"html":"<p>1 בריאה creation  ירוש׳ נדה פ״ג נ׳ ע״ג: יצירה באדם וכו׳ יצירה בבהמה.\n2 בית מלאכת יוצר כלי חרס pottery  תוס׳ ב״מ ח׳ כ״ז: השוכר חנות וכו׳ גת וכו׳ ויצירה אין פחות משנים עשר חדש.</p>","notation":["נ׳"]},"39214":{"h":"יְצִירַת הַוָּולָד","r":"KRU08786","alt":[],"source":"krupnik","glosses":[{"text":"the formation of the embryo","label":""}],"html":"<p>התרקמות אברי הוולד במעי אמו the formation of the embryo  סוטה ב׳ ע״א: ארבעים יום קודם יצירת הוולד בת קול יוצאת ואומרת בת פלוני לפלוני.</p>","notation":[]},"39215":{"h":"יְצִירִין","r":"KRU08787","alt":[],"source":"krupnik","glosses":[{"text":"the implements of the olive press","label":""}],"html":"<p>כלי הבד the implements of the olive press  תוס׳ ב״ב ג׳ ב׳: המוכר את בית הבד מכר את היצירין.</p>","notation":["ז״ר"]},"39216":{"h":"יצע","r":"KRU08788","alt":[],"source":"krupnik","glosses":[{"text":"to spread, to lay out the mattresses","label":"הפ׳ הִצִּיעַ 1"},{"text":"to arrange, to lay before …","label":"הפ׳ הִצִּיעַ 2"}],"html":"<p>הפ׳ הִצִּיעַ 1 פרס סדין וכדומה to spread, to lay out the mattresses  כת׳ פ״ה מ״ה: אלו מלאכות שהאשה עושה לבעלה וכו׳ ומצעת לו המטה.\nהפ׳ הִצִּיעַ 2 הרצה דברים to arrange, to lay before …  בר׳ כ״ב ע״א: מציע הוא את המשנה ואינו מציע את הגמרא.</p>","notation":["Source marks no qal form"]},"39217":{"h":"יְצֵף","r":"KRU08790","alt":[],"source":"krupnik","glosses":[{"text":"to be afraid, to trouble","label":"פַעל, אתפ׳,"}],"html":"<p>פַעל, אתפ׳, יַצֵּף אִתְיְצֵף to be afraid, to trouble  תרג׳ ירמ׳ מ״ב ט״ז (והרעב אשר אתם דואגים ממנו): וכפנא דאתון יצפין מיניה; שם ל״א י״א (ולא יוסיפו לדאבה עוד): ולא יוספון ליצפא עוד; תרג׳ תה׳ ל״ח י״ט (אדאג מחטאתי): אתיצף מן חטאי.</p>","notation":[]},"39218":{"h":"יִצְפָּא","r":"KRU08791","alt":[],"source":"krupnik","glosses":[{"text":"trouble","label":""}],"html":"<p>דאגה וחשש trouble  תרג׳ יח׳ ד׳ ט״ז (ובדאגה): וביצפא.</p>","notation":["ז׳"]},"39219":{"h":"יָצַר","r":"KRU08792","alt":[],"source":"krupnik","glosses":[{"text":"to be fully developed","label":"נוֹצַר נפ׳"}],"html":"<p>נוֹצַר נפ׳ ·– נתרקמו האברים של גוף הוולד to be fully developed  ירוש׳ יבמ׳ פ״ד ה׳ ע״ד: נוצר לז׳ ונולד לשמונה חי.</p>","notation":["Marked biblical in source"]},"39220":{"h":"יְצַר","r":"KRU08793","alt":[],"source":"krupnik","glosses":[{"text":"to be formed","label":"אִיתְּצַר אתפ׳,"}],"html":"<p>אִיתְּצַר אתפ׳, התרקם חיתוך האברים to be formed  יומא פ״ה ע״א: ממציעתיה מיתצר.</p>","notation":["Source marks no qal form"]},"39221":{"h":"יֵצֶר טוֹב","r":"KRU08795","alt":[],"source":"krupnik","glosses":[{"text":"the good genius","label":""}],"html":"<p>הנטיה הטובה של אדם the good genius  ירוש׳ בר׳ פ״ד ז׳ ע״ד: יהי רצון וכו׳ שתתן לי לב טוב יצר טוב סבר טוב.</p>","notation":[]},"39222":{"h":"יֵצֶר רָע","r":"KRU08796","alt":[],"source":"krupnik","glosses":[{"text":"the evil inclination","label":""}],"html":"<p>הנטיה הרעה שבאדם the evil inclination  ב״ב ט״ו ע״א: הוא שטן הוא יצר הרע.</p>","notation":[]},"39223":{"h":"יָצַת","r":"KRU08798","alt":[],"source":"krupnik","glosses":[{"text":"to be kindled","label":"הוּצַת הופ׳"}],"html":"<p>הוּצַת הופ׳ הודלק to be kindled  במ״ר פי״ב: דומה לגפרית מוצתה באש.</p>","notation":["Marked biblical in source"]},"39224":{"h":"יָקָא","r":"KRU08799","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ שבת פ״ז י׳ ע״ב: ר׳ חנינא בן יקא. </p>","notation":["שם איש"]},"39225":{"h":"יָקַב","r":"KRU08800","alt":[],"source":"krupnik","glosses":[{"text":"to hollow out","label":""}],"html":"<p>עשה חלול ונבוב to hollow out  שהש״ר ז׳ ה׳: עד היקבים שיקבן מלך מלכי המלכים.</p>","notation":["פ״י"]},"39226":{"h":"יָקַד","r":"KRU08801","alt":[],"source":"krupnik","glosses":[{"text":"to set on fire","label":"הוֹקִיד הפ׳,"},{"text":"to burn","label":"נִתְוַקֵּד נתפ׳,"}],"html":"<p>הוֹקִיד הפ׳, שרף to set on fire  ב״ר פמ״ח: אילו ניתנה רשות וכו׳ היו מוקדים.\nנִתְוַקֵּד נתפ׳, בער ויקד to burn  ויק״ר פ״ז: קרוב למאה ושש עשרה שנה היתה האש מתוקדת בו עצו לא נשרף ונחשתו לא ניתך.</p>","notation":["Marked biblical in source"]},"39227":{"h":"יְקַד","r":"KRU08802","alt":[],"source":"krupnik","glosses":[{"text":"to burn","label":""},{"text":"to set on fire","label":""},{"text":"to be burnt","label":""}],"html":"<p>1) פ״ע בער to burn  תרג׳ יש׳ י׳ ט״ז (יקד יקוד): מיקד ייקדון. 2) שרף to set on fire  שהש״ר ג׳ ד׳: דרא יקידא יקדת. אוֹקִיד  אפ׳, כנ״ל 2. איכ״ר פתיחתא סוף: ואוקיד דרעיה. אִתּוֹקד, אִיַּקַּד אתפ׳, נשרף to be burnt  תרג׳ יר׳ ל״ח כ״ג: תתוקד בנורא; ירוש׳ חג׳ פ״ב ע״ז ע״ג: קבריה דרבך אייקד. </p>","notation":[]},"39228":{"h":"יְקוֹד","r":"KRU08803","alt":[],"source":"krupnik","glosses":[{"text":"burning","label":""}],"html":"<p>דליקה burning  ר״ה כ״ב ע״ב: מאי משמע דהאי משיאין לישנא דיקוד הוא.</p>","notation":["ז׳"]},"39229":{"h":"יָקוּם","r":"KRU08804","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  מדר׳ תה׳ י״א: יקום איש צרורות. </p>","notation":["שם איש"]},"39230":{"h":"יְקוּמִינִי","r":"KRU08805","alt":[],"source":"krupnik","glosses":[{"text":"world","label":""}],"html":"<p>תבל world  ב״ר פל״ב: היקום – יקומיני.</p>","notation":["נ׳"]},"39231":{"h":"יְקוּנְתְּיָה","r":"KRU08806","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ירוש׳ מ״ק פ״ג פ״ד ע״ג: גמליאל דיקונתיה. </p>","notation":["שם מקום"]},"39232":{"h":"יְקִידָא","r":"KRU08807","alt":["יְקִידָה","יְקִידוּתָא","יְקֵידְתָּא"],"source":"krupnik","glosses":[{"text":"fire, burning","label":""}],"html":"<p>שריפה fire, burning  תרג׳ עמ׳ ד׳ י״א (כאוד מוצל משרפה): כאוד משיזא מיקידא; שבת פ״ב ע״א: לחתות אש מיקידה גדולה; תרג׳ יש׳ ל״ג י״ד (מוקדי עולם): יקידות עולם; איוב ג׳ כ״ו: בסורתא דיקידתא.</p>","notation":["ז׳"]},"39233":{"h":"יַקִּיר","r":"KRU08808","alt":[],"source":"krupnik","glosses":[{"text":"honourable, noble","label":""}],"html":"<p>נכבד ונשוא פנים honourable, noble  סוכה ל״ז ע״א: מעשה ביקירי ירושלים שהיו אוגדין את לולביהן בגימוניות של זהב.</p>","notation":["Marked biblical in source"]},"39234":{"h":"יַקִּירָא","r":"KRU08809","alt":[],"source":"krupnik","glosses":[{"text":"heavy","label":"1"},{"text":"honored","label":"2"},{"text":"dear, precious","label":"3"}],"html":"<p>1 כבד heavy  תרג׳ מש׳ כ״ז ב׳ (כבד אבן): יקירא כיפא.\n2 נכבד honored  תרג׳ במ׳ כ״ב ט״ו (רבים ונכבדים מאלה): סגיאין ויקירין מאלין.\n3 יקר המחיר dear, precious  תרג׳ מש׳ ג׳ ט״ו (יקרה היא מפנינים): יקירא היא מן כיפי טבאתא.</p>","notation":["ת׳"]},"39235":{"h":"יַקִּירוּ","r":"KRU08810","alt":[],"source":"krupnik","glosses":[{"text":"dignity","label":""}],"html":"<p>חשיבות dignity  קהל״ר י״א א׳: את חכים ביקירו דברייתא.</p>","notation":["נ׳"]},"39236":{"h":"יָקָם","r":"KRU08811","alt":[],"source":"krupnik","glosses":[{"text":"a vessel in the bathinghouse","label":""}],"html":"<p>מין ספל במרחץ a vessel in the bathinghouse  ב״ב ס״ז ע״ב: המוכר את המרחץ מכר את בית הנסכין ואת בית היקמין וכו׳ ולא יקמין עצמן.</p>","notation":["ז׳"]},"39237":{"h":"יָקַר","r":"KRU08814","alt":[],"source":"krupnik","glosses":[{"text":"to grow heavy","label":""}],"html":"<p>נעשה כבד to grow heavy  מכי׳ בשלח עמלק ב׳: יקרו ידיו של משה באותה שעה כאדם שתלויין לו בדין של מים.</p>","notation":["Marked biblical in source"]},"39238":{"h":"יִקֵּר","r":"KRU08815","alt":[],"source":"krupnik","glosses":[{"text":"to honour","label":"פיעל, 1"},{"text":"to be proud","label":"פיעל, 2"},{"text":"to grow dear","label":"הוֹקִיר·– הפ׳"}],"html":"<p>פיעל, 1 כיבד to honour  דב״ר פ״ז: אני מגדיל ומייקר אתכם לעתיד לבא.\nפיעל, 2 התגאה to be proud  ב״ר פי״ח: מיקרת ראשה.\nהוֹקִיר·– הפ׳ נעשה יקר to grow dear  ירוש׳ כת׳ פי״ב ל״ד ע״ד: היו בזול והוקירו.\nהוּקַר הופ׳, כנ״ל. ב״ב פ״ה מ״ח: והוקרו או שהוזלו. \nהִתְיַקֵּר התפ׳, עי׳ יָקַר. במ״ר פ״ר: ולמה היו הקנים עשויים כחצי קנה חלול כדי שלא יתיקרו על הלחם. </p>","notation":[]},"39239":{"h":"יְקַר","r":"KRU08816","alt":[],"source":"krupnik","glosses":[{"text":"to be heavy","label":""},{"text":"to be dear","label":""},{"text":"to make heavy","label":""},{"text":"to honour","label":""},{"text":"to make a present","label":""},{"text":"to become difficult","label":""},{"text":"to be honoured","label":""},{"text":"to rise in value","label":""}],"html":"<p>1) היה כבד to be heavy  תרג׳ יב״ע בר׳ מ״ה י׳ (ועיני ישראל כבדו): ועיני ישראל יקרן. 2) היה יקר to be dear  ב״מ ס״ד ע״א: אי יקרא וכו׳. יַקֵּר פעל 1) הכביד to make heavy  תרג׳ איכה ג׳ ז׳ (הכביד נחשתי): יקר על ריגליי כבלין. 2) כיבד to honour  תרג׳ מש׳ ד׳ ח׳ (תכבדה כי תחבקנה): וחבקיה דתיקריך. אוֹקִיר, אַיְקַר אפ׳ 1) כנ״ל 2. שבת כ״ג ע״ב: דמוקר רבנן; ירוש׳ פאה פ״א ט״ו ע״ג: הלואי חוה לי אבא ואימא דאיקרינהון. 2) נתן במתנה to make a present  ירוש׳ ב״ב פ״ב י״ג ע״ג: חדא אתתא אוקרת תאינין לר׳ יונתן. אִתְיַקַּר, אִיַּקַּר אתפ׳ 1) נעשה כבד to become difficult  ע״ז מ״ו ע״ב: אייקר ליה תלמודא. 2) היה נכבד to be honoured  מגי׳ כ״ח ע״א: אתייקורי דמתייקרי בי. 3) נתיקר במחירו to rise in value  ב״ק ק״ג ע״א: אייקר כיתנא. </p>","notation":["פ״ע"]},"39240":{"h":"יַקְרוּת","r":"KRU08817","alt":[],"source":"krupnik","glosses":[{"text":"dignity","label":""}],"html":"<p>חשיבות dignity  איכ״ר ד׳: מה היתה יקרותן שלא היה אחד מהן הולך לסעודה עד שהיה יודע עם מי הוא סועד.</p>","notation":["נ׳"]},"39241":{"h":"יַקְשָׁן","r":"KRU08818","alt":[],"source":"krupnik","glosses":[{"text":"bandy-legged","label":""}],"html":"<p>בעל רגלים עקומות bandy-legged  תוס׳ בכורות ה׳ ט׳: הזיוד וכו׳ והיקשן פסולין באדם וכשרין בבהמה. יר׳ ירמיהו.</p>","notation":["ת׳"]},"39242":{"h":"יָרֵא","r":"KRU08821","alt":[],"source":"krupnik","glosses":[{"text":"pious","label":""}],"html":"<p>חסיד וירא אלהים pious  במ״ר פט״ו: שהוא חולק ליראיו מכבודו.</p>","notation":["Marked biblical in source"]},"39243":{"h":"יְרֵא חֵטְא","r":"KRU08822","alt":[],"source":"krupnik","glosses":[{"text":"shunning sin","label":""}],"html":"<p>צדיק, מתרחק מחטא shunning sin  אבות פ״ב מ״ה: אין בור ירא חטא ולא עם הארץ חסיד.</p>","notation":[]},"39244":{"h":"יְרֵא שָׁמַיִם","r":"KRU08823","alt":[],"source":"krupnik","glosses":[{"text":"God-fearing","label":""}],"html":"<p>ירא אלהים God-fearing  בר׳ ח׳ ע״א: גדול הנהנה מיגיעו יותר מירא שמים.</p>","notation":[]},"39245":{"h":"יָרֵא²","r":"KRU08824","alt":[],"source":"krupnik","glosses":[{"text":"to be afraid","label":"הִתְיָרֵא התפ׳ 1"},{"text":"to be feared","label":"הִתְיָרֵא התפ׳ 2"}],"html":"<p>הִתְיָרֵא התפ׳ 1 פחד to be afraid  סוטה פ״ז מ״ח: אל תתירא אגריפס אחינו אתה.\nהִתְיָרֵא התפ׳ 2 היה נורא על סביביו to be feared  זבח׳ קט״ו ע״ב: מתיירא ומתעלה.</p>","notation":["Marked biblical in source"]},"39246":{"h":"יִרְאָה","r":"KRU08825","alt":[],"source":"krupnik","glosses":[{"text":"idol","label":""}],"html":"<p>·– אליל idol  ירוש׳ בר׳ פ״ט י״ג ע״ב: והתחיל נוטל יראתו בידו וקורא ולא הועיל כלום.</p>","notation":[]},"39247":{"h":"יִרְאַת חֵטְא","r":"KRU08826","alt":[],"source":"krupnik","glosses":[{"text":"fear of sin","label":""}],"html":"<p>התרחקות מחטא– fear of sin  שמו״ר פ״ל: אתה מוצא אדם שונה מדרש הלכות ואגדות ואם אין בו יראת חטא אין בו כלום.</p>","notation":[]},"39248":{"h":"יִרְאַת שָׁמַיִם","r":"KRU08827","alt":[],"source":"krupnik","glosses":[{"text":"fear of the Lord","label":""}],"html":"<p>יראת אלהים fear of the Lord  בר׳ ל״ג ע״ב: הכל בידי שמים חוץ מיראת שמים.</p>","notation":[]},"39249":{"h":"יָרְאוּי","r":"KRU08828","alt":[],"source":"krupnik","glosses":[{"text":"feared","label":""}],"html":"<p>שהכל יראים ממנו feared  כר׳ ל״ג ע״ב: האל הגדול הגבור והנורא והאדיר והעזוז והיראוי וכו׳.</p>","notation":["ת׳"]},"39250":{"h":"יַרְבּוּז","r":"KRU08829","alt":["יַרְבּוּזָה"],"source":"krupnik","glosses":[{"text":"strawberry-blite","label":""}],"html":"<p>מין ירק strawberry-blite  תוס׳ כלא׳ א׳ י״א: ואין מרכיבין וכו׳ ולא תרד על גבי ירבוז מפני שירק בירק; ירוש׳ כלא׳ פ״ה ל׳ ע״א: הדין ירבוזה.</p>","notation":[]},"39251":{"h":"יָרַד לְנִכְסֵי־","r":"KRU08830","alt":[],"source":"krupnik","glosses":[{"text":"to seize, to take possession of","label":""}],"html":"<p>לקח את הנכסים לרשותו to seize, to take possession of  ירוש׳ יבמ׳ פט״ו ט״ו ע״א: היורד לנכסי שבויין ושמע עליהן שהן ממשמשין ובאין.</p>","notation":[]},"39252":{"h":"יָרַד לִפְנֵי הַתֵּיבָה","r":"KRU08831","alt":[],"source":"krupnik","glosses":[{"text":"to act as reader of prayers","label":""}],"html":"<p>התפלל כשליח צבור לפני העמוד בבית הכנסת to act as reader of prayers  תענ׳ כ״ה ע״א: מעשה בר״א שירד לפני התיבה ואמר עשרים וארבע ברכות.</p>","notation":[]},"39253":{"h":"יָרַד מִנְּכָסָיו","r":"KRU08832","alt":[],"source":"krupnik","glosses":[{"text":"to become poor","label":""}],"html":"<p>נתרושש to become poor  ב״ק פ״ח מ״ו: אפילו עניים שבישראל רואין אותם כאילו הם בני חורין שירדו מנכסיהם.</p>","notation":[]},"39254":{"h":"יָרַד עַד לְחַיָיו","r":"KRU08833","alt":[],"source":"krupnik","glosses":[{"text":"to deprive one of his livelihood","label":""},{"text":"to appoint as administrator","label":""},{"text":"to impoverish","label":""}],"html":"<p>הזיק לפרנסתו to deprive one of his livelihood  שמו״ר פ״א: יורד עמו עד לחייו. הוֹרִיד הפ׳ ·– הוֹרִיד לְנִכְסֵי־ נתן רשות לשלוט בנכסים to appoint as administrator  ב״מ ל״ח ע״ב: מורידין קרוב לנכסי שבוי. הוֹרִיד מִנְּכְסֵי־ הוריש, דלדל to impoverish  ירוש׳ ב״ק פ״ד ד׳ ע״ב: הורידן מנכסיהן. </p>","notation":[]},"39255":{"h":"יָרָה","r":"KRU08835","alt":[],"source":"krupnik","glosses":[{"text":"to decide","label":"הוֹרָה הפ׳"}],"html":"<p>הוֹרָה הפ׳ ·– ·– פסק הלכה to decide  הור׳ פ״א מ״ב: הורו בי״ד וידעו שטעו וחזרו בהן.</p>","notation":[]},"39256":{"h":"יַרְוָאר","r":"KRU08836","alt":[],"source":"krupnik","glosses":[{"text":"aralia","label":""}],"html":"<p>. מין צמח aralia פס׳ ל״ט ע״א: ומר זה הוא ירואר.</p>","notation":["ז׳"]},"39257":{"h":"יָרוּד","r":"KRU08837","alt":[],"source":"krupnik","glosses":[{"text":"low, common","label":""}],"html":"<p>פחות, גרוע, שפל low, common  שמ״ר פ״מ: אין לך גדול משבט יהודה ואין לך ירוד משבט דן.</p>","notation":["ת׳"]},"39258":{"h":"יָרוֹד","r":"KRU08838","alt":[],"source":"krupnik","glosses":[{"text":"an eye-disease","label":"1"},{"text":"a bird","label":"2"}],"html":"<p>1 מין מחלה שבעין an eye-disease  מכי׳ משפ׳ נזיק׳ ט׳: את עין עבדו שומע אני אפילו העלת ירוד וכו׳.\n2 מין עוף a bird  תוס׳ כלא׳ ה׳ ח׳: הירודין והנעמיות.</p>","notation":["ז׳"]},"39259":{"h":"יָרוֹק","r":"KRU08839","alt":[],"source":"krupnik","glosses":[{"text":"green","label":"1"},{"text":"yellow","label":"2"}],"html":"<p>1 מצבע הירק והעשב green  סוכה פ״ג מ״ו: אתרוג הכושי וכו׳ והירוק ככרתי.\n2 כתום, צהוב yellow  עדי׳ פ״ה מ״ו: ודם הירוק.</p>","notation":["ת׳"]},"39260":{"h":"יָרוֹקָא","r":"KRU08840","alt":[],"source":"krupnik","glosses":[{"text":"yellow, greenish","label":"1"},{"text":"foliage","label":"2"},{"text":"a species of fish","label":"3"}],"html":"<p>1  yellow, greenish  תרג׳ יב״ע במ׳ ב׳ ג׳: סמוקא וירוקא.\n2  foliage  תרג׳ איוב ל״ט ח׳ (אחר כל ירוק י׳ דרוש:) ובתר כל ירוקא יתבע.\n3 מין דג a species of fish  ירוש׳ כלא׳ פ״א כ״ז ע״א: לכיסא וכו׳ ירוקא.</p>","notation":[]},"39261":{"h":"יְרוֹקָא","r":"KRU08841","alt":[],"source":"krupnik","glosses":[{"text":"a sort of moss","label":"1"},{"text":"green colour","label":"2"},{"text":"jaundice","label":"3"}],"html":"<p>1 מין טחב הגדל במים a sort of moss  שבת פ״ב מ״א: אין מדליקין לא בלכש וכו׳ ולא בירוקה שעל פני המים.\n2 גוון הירוק green colour  חול׳ נ״ו ע״ב: שיעור ירוקתן כשיעור נקובתן מה נקובתן במשהו אף ירוקתן במשהו.\n3 מין מחלה jaundice  שבת פי״ד מ״ג: כוס עיקרין מפני שהן לירוקה.</p>","notation":["נ׳"]},"39262":{"h":"יֵרוֹקָן","r":"KRU08842","alt":[],"source":"krupnik","glosses":[{"text":"greens","label":""}],"html":"<p>ירק greens  תרג׳ מל״ב ד׳ ל״ט (ללקט ארת): ללקטא ירוקנין.</p>","notation":["ז׳"]},"39263":{"h":"יְרוֹקְתָּא","r":"KRU08843","alt":[],"source":"krupnik","glosses":[{"text":"a precious stone","label":""}],"html":"<p>מין אבן טובה a precious stone  תרג׳ יב״ע שמ׳ ל״ט י׳ (פטדה): ירוקתא.</p>","notation":["נ׳"]},"39264":{"h":"יְרוּשַׁלְמָאָה","r":"KRU08845","alt":["יְרוּשַׁלְמִי"],"source":"krupnik","glosses":[{"text":"of Jerusalem, Jerusalemite","label":""}],"html":"<p>מירושלים of Jerusalem, Jerusalemite  איכ״ר פתיחתא (ר׳ יוחנן א׳): כל נביא שלא נתפרש שם עירו ירושלמי היה: ב״ק ו׳ ע״ב: האי תנא ירושלמאה הוא.</p>","notation":[]},"39265":{"h":"יָרוֹתָא","r":"KRU08846","alt":[],"source":"krupnik","glosses":[{"text":"heir","label":""}],"html":"<p>יורש heir  תרג׳ ש״ב י״ד ז׳ (ונשמידה גם את היורש): ונשיצי אף ירותא.</p>","notation":["ז׳"]},"39266":{"h":"יְרוּתָא","r":"KRU08847","alt":["יְרוּתְּתָא"],"source":"krupnik","glosses":[{"text":"heirdom, heirloom","label":"1"},{"text":"possession","label":"2"}],"html":"<p>1 ירושה heirdom, heirloom  ב״ר פנ״ו: כל אותן הפרגזיות וכו׳ שנאיה דביתא ירותא; ויק״ר פי״ח: ירותתי גבך.\n2 נחלה, אחוזה, קנין possession  תרג׳ במ׳ כ״ד י״ח (והיה אדום ירשה): ויהי אדום ירותא; יש׳ י״ד כ״ג (מורש קפוד): לירותת קופדין.</p>","notation":[]},"39267":{"h":"יַרְחָא","r":"KRU08848","alt":[],"source":"krupnik","glosses":[{"text":"month","label":""}],"html":"<p>יֶרח, חודש month  ביצה ד׳ ע״ב: והשתא דידעינן בקביעא דירחא.</p>","notation":["ז׳"]},"39268":{"h":"יַרְחִינָאָה","r":"KRU08849","alt":[],"source":"krupnik","glosses":[{"text":"astronomer","label":""}],"html":"<p>בקי בחכמת התכונה astronomer  ב״מ פ״ה ע״ב: שמואל ירחינאה אסייה דרבי.</p>","notation":["ז׳"]},"39269":{"h":"ירי","r":"KRU08850","alt":[],"source":"krupnik","glosses":[{"text":"to teach","label":"אוֹרִי אפ׳,"}],"html":"<p>אוֹרִי אפ׳, הורה ולימד to teach  ירוש׳ מעש׳ פ״א מ״ט ע״א: הורי ר׳ חנינא וכו׳.</p>","notation":["Source marks no qal form"]},"39270":{"h":"ירי²","r":"KRU08851","alt":[],"source":"krupnik","glosses":[{"text":"a word in a charm formula","label":""}],"html":"<p>תיבה בנוסח של לחש a word in a charm formula  פס׳ קי״ב ע״א: שברירי ברירי רירי ירי וכו׳.</p>","notation":[]},"39271":{"h":"יָרִיד","r":"KRU08852","alt":[],"source":"krupnik","glosses":[{"text":"fair","label":""}],"html":"<p>שוק גדול ביום קבוע ובמקום קבוע fair  תוס׳ ע״ז א׳ ט׳: תגרים שהקדימו זמנו של יריד או שאיחרו זמנו של יריד.</p>","notation":["ז׳"]},"39272":{"h":"יְרִידָה","r":"KRU08853","alt":[],"source":"krupnik","glosses":[{"text":"going down, fall","label":""}],"html":"<p>פעולת היורד, נפילה going down, fall  מכות פ״ב מ״א: היה יורד בסולם ונפל עליו והרגו וכו׳ כל שבדרך ירידתו גולה וכו׳; ירוש׳ תענ׳ פ״א ס״ג ע״ג: ירידת הגשמים.</p>","notation":["נ׳"]},"39273":{"h":"יְרִיָּיה","r":"KRU08854","alt":[],"source":"krupnik","glosses":[{"text":"shooting","label":""}],"html":"<p>מלאכת הקלע והרובה shooting  ילק׳ בר׳ קל״ג: קליעת אבנים ויריית חצים.</p>","notation":["נ׳"]},"39274":{"h":"יְרִיָעה","r":"KRU08855","alt":[],"source":"krupnik","glosses":[{"text":"a writing sheet","label":""}],"html":"<p>גליון של קלף במגילה a writing sheet  סופר׳ ב׳ ו׳: אין פוחתין ביריעה פחות משלשה דפין ולא מוסיפין על שמונה.</p>","notation":["Marked biblical in source"]},"39275":{"h":"יְרִיעֲתָא","r":"KRU08856","alt":[],"source":"krupnik","glosses":[{"text":"curtain","label":""}],"html":"<p>מסך curtain  תרג׳ תה׳ ק״ד ב׳ (כיריעה): היך יריעתא.</p>","notation":["נ׳"]},"39276":{"h":"יָרֵךְ","r":"KRU08857","alt":[],"source":"krupnik","glosses":[{"text":"the perpendicular stroke of a letter, leg","label":""}],"html":"<p>רגל האות the perpendicular stroke of a letter, leg  ירוש׳ מגי׳ פ״א ע״א ע״ג: ניקב נקב בירכו של הא אם גרדו ונשתייר שם ירך קטנה כשר.</p>","notation":["Marked biblical in source"]},"39277":{"h":"יַרְכָא","r":"KRU08858","alt":["יַרְכוּנָא"],"source":"krupnik","glosses":[{"text":"thigh","label":""}],"html":"<p>שוק העליון thigh  תרג׳ שמ׳ א׳ ה׳ (יוצאי ירך יעקב): נפקי ירכא דיעקב; יב״ע במ׳ ה׳ כ״ב (לנפיל ירך): למסיא ירכונין.</p>","notation":[]},"39278":{"h":"יַרְמוּךְ","r":"KRU08861","alt":[],"source":"krupnik","glosses":[{"text":"Jarmukh, a river in Palestine","label":""}],"html":"<p>נהר בארץ ישראל Jarmukh, a river in Palestine  פרה פ״ח מ״י: מי הירדן ומי ירמוך פסולים מפני שהם מי תערובות.</p>","notation":[]},"39279":{"h":"יַרְמַטְיָה","r":"KRU08862","alt":[],"source":"krupnik","glosses":[{"text":"a woman’s name","label":""}],"html":"<p>שם אשה a woman’s name  ערכ׳ פ״ה מ״א: מעשה באמה של ירמטיה שאמרה משקל בתי עלי.</p>","notation":[]},"39280":{"h":"יְרַנְקָא","r":"KRU08863","alt":[],"source":"krupnik","glosses":[{"text":"bitter wine","label":""}],"html":"<p>יין מר bitter wine  ע״ז ל׳ ע״א: מר ירנקא.</p>","notation":["ז׳"]},"39281":{"h":"יַרְעֲנָה","r":"KRU08864","alt":[],"source":"krupnik","glosses":[{"text":"a plant used as soap","label":""}],"html":"<p>מין צמח שמשתמשים בו לכבוס a plant used as soap  תוס׳ שבי׳ ה׳ ו׳: והירענה והבורית וכו׳.</p>","notation":["נ׳"]},"39282":{"h":"יָרַק","r":"KRU08865","alt":[],"source":"krupnik","glosses":[{"text":"to become green","label":"הוֹרִיק הפ׳, 1"},{"text":"to make green","label":"הוֹרִיק הפ׳, 2"},{"text":"to make glisten","label":"הוֹרִיק הפ׳, 3"},{"text":"to defy","label":"הוֹרִיק פָּנִים הפ׳,"}],"html":"<p>הוֹרִיק הפ׳, 1 נעשה ירוק to become green  רות רבה א׳ ז׳: לשעבר היו פניה מאדימות מכח מאכל ומשתה ועכשיו פניה מוריקות מן רעבון.\nהוֹרִיק הפ׳, 2 עשה ירוק to make green  בר׳ מ״ד ע״ב: כל ירק חי מוריק.\nהוֹרִיק הפ׳, 3 נתן זיו וזוהר to make glisten  ב״ר פמ״ג: באבנים טובות ומרגליות הוריקן.\nהוֹרִיק פָּנִים הפ׳, התריס כנגד to defy  ב״ר פמ״ג: הן הוריקו פנים כנגד אברהם וכו׳.</p>","notation":["Marked biblical in source"]},"39283":{"h":"יְרַק","r":"KRU08866","alt":[],"source":"krupnik","glosses":[{"text":"to become green (yellow)","label":"אוֹרִיק אפ׳,"}],"html":"<p>אוֹרִיק אפ׳, נעשה ירוק to become green (yellow)  תרג׳ יב״ע ויק׳ ט״ו י״ט: מוריק הִי כגון זעפרנא.</p>","notation":["Source marks no qal form"]},"39284":{"h":"יַרְקָא","r":"KRU08867","alt":[],"source":"krupnik","glosses":[{"text":"greens","label":"1"},{"text":"green","label":"2"}],"html":"<p>1  greens  שבת ק״מ ע״ב: היכא דליעול ירקא ליעול בישרא וכוורא.\n2  green  תרג׳ איוב כ״ח י״ט (פטדת כוש): מרגלא ירקא דאתי מן כוש.</p>","notation":[]},"39285":{"h":"יֵרָקוֹן","r":"KRU08868","alt":[],"source":"krupnik","glosses":[{"text":"jaundice","label":""}],"html":"<p>מין מחלה jaundice  בר׳ כ״ה ע״א: סילון החוזר מביא את האדם לידי ירקון.</p>","notation":["Marked biblical in source"]},"39286":{"h":"יַרְקוּת חֲמוֹר","r":"KRU08869","alt":[],"source":"krupnik","glosses":[{"text":"squirting cucumber (bot.)","label":""}],"html":"<p>מין קשוא squirting cucumber (bot.)  אהל׳ פ״ח מ״א: וירקות חמור ודלעת יונית.</p>","notation":[]},"39287":{"h":"יַרְקָן","r":"KRU08870","alt":[],"source":"krupnik","glosses":[{"text":"a precious stone","label":""}],"html":"<p>מין אבן טובה a precious stone  תרג׳ שמ׳ כ״ח י״ז (פטדה): ירקן.</p>","notation":["ז׳"]},"39288":{"h":"יַרְקָנָא","r":"KRU08871","alt":[],"source":"krupnik","glosses":[{"text":"mildew","label":""}],"html":"<p>ירקון, מחלת התבואה mildew  תרג׳ עמ׳ ד׳ ט׳ (בירקון): בירקנא.</p>","notation":["ז׳"]},"39289":{"h":"יְרַקְרוֹק","r":"KRU08872","alt":[],"source":"krupnik","glosses":[{"text":"greenish","label":""}],"html":"<p>ירקרק, ירוק קצת greenish  מגי׳ י״ג ע״א: אסתר ירקרוקת היתה וחוט של חסד משוך עליה.</p>","notation":["ת׳"]},"39290":{"h":"יְרַקְרֵיקָא","r":"KRU08873","alt":[],"source":"krupnik","glosses":[{"text":"a bird","label":""}],"html":"<p>מין עוף a bird  תרג׳ ויק׳ י״א י״ח (הרחם): ירקריקא.</p>","notation":["ז׳"]},"39291":{"h":"יְרֵת","r":"KRU08876","alt":[],"source":"krupnik","glosses":[{"text":"to inherit","label":""},{"text":"to bequeathe","label":""}],"html":"<p>ירש to inherit  כת׳ פ״ד מ״י: אינוק ירתין. אוֹרִית  אפ׳, הוריש, הנחיל to bequeathe  תרג׳ מש׳ י״ג כ״ב (ינחיל בני בנים): מורית לבני בנוהי. </p>","notation":["פ״י"]},"39292":{"h":"יָרְתָא","r":"KRU08877","alt":[],"source":"krupnik","glosses":[{"text":"heir","label":""}],"html":"<p>יורש heir  ירוש׳ סנה׳ פ״ג כ״א ע״ד: כתב ר׳ לעזר לירתוי ספרים שזכת בהן ארץ ישראל אין מוציאין אותן חוצה לארץ.</p>","notation":["ז׳"]},"39293":{"h":"יֵרְתוּ","r":"KRU08878","alt":[],"source":"krupnik","glosses":[{"text":"heirloom, legacy","label":""}],"html":"<p>ירושה heirloom, legacy  ירוש׳ סנה׳ פ״ג כ״א ע״ד: כהנא דמך ושבק ירתו לר׳ יאשיה.</p>","notation":["נ׳"]},"39294":{"h":"יֵשׁ יֵשׁ אוֹמְרִים","r":"KRU08881","alt":[],"source":"krupnik","glosses":[{"text":"some say","label":""},{"text":"there is no(t)","label":""}],"html":"<p>קצת חכמים סבורים some say  ב״ב צ״ג ע״ב: מאן יש אומרים. לֹא יֵשׁ אין there is no(t)  דב״ר פ״ח: תן דעתך עליה ושמור אותה כראוי שאם תאבד לא יש לי אחרת כיוצא בה. </p>","notation":["Marked biblical in source"]},"39295":{"h":"יָשַׁב יָשַׁב בְּרֹאשׁ","r":"KRU08883","alt":[],"source":"krupnik","glosses":[{"text":"to preside","label":""}],"html":"<p>to preside  כת׳ ק״ג ע״ב: חנינא בר חמא ישב בראש. </p>","notation":["Marked biblical in source"]},"39296":{"h":"יָשַׁב בְּתַעֲנִית","r":"KRU08884","alt":[],"source":"krupnik","glosses":[{"text":"to fast","label":""}],"html":"<p>צם והתענה to fast  עיר׳ י״ח ע״ב: כיון שראה אדם הראשון שנקנסה מיתה על ידו ישב בתענית.</p>","notation":[]},"39297":{"h":"יִשֵּׁב","r":"KRU08885","alt":[],"source":"krupnik","glosses":[{"text":"to put in place","label":"פיעל 1"},{"text":"to quiet","label":"פיעל 2"},{"text":"to seat","label":"הוֹשִׁיב·– הפ׳"},{"text":"to establish one's self","label":"נִתְיַשֵּׁב נתפ׳, 1"},{"text":"to rest","label":"נִתְיַשֵּׁב נתפ׳, 2"},{"text":"to be settled","label":"נִתְיַשֵּׁב נתפ׳, 3"},{"text":"to be secured","label":"נִתְיַשֵּׁב נתפ׳, 4"},{"text":"to come to","label":"נִתְיַשֵּׁב נתפ׳, 5"}],"html":"<p>פיעל 1 קבע to put in place  ירוש׳ שבת פ״ז י׳ ע״ד: הבנאי שקבע את האבן בראש הדימוס.\nפיעל 2 הניח את הדעת to quiet  ב״ר פ״פ: וידבר על לב הנערה וכו׳ דברים שמישבים את הלב.\nהוֹשִׁיב·– הפ׳ נתן לו מקום לשבת to seat  יומא ל״ח ע״א: בשמך יקראוך ובמקומך יושיבוך ומשלך יתנו לך.\nנִתְיַשֵּׁב נתפ׳, 1  to establish one&#x27;s self  ספרא אחרי קל״ח: ואותו המקום שנתישבו בו ישראל וכו׳.\nנִתְיַשֵּׁב נתפ׳, 2 נח to rest  תנח׳ במ׳ י״ג: כיון שנתיישבו תקעו בחצוצרות ונסע יהודה ודגלו תחלה.\nנִתְיַשֵּׁב נתפ׳, 3 נושב to be settled  בר׳ ל״א ע״א: כל ארץ שגזר עליה אדם הראשון לישוב נתישבה וכו׳.\nנִתְיַשֵּׁב נתפ׳, 4 נתחזק to be secured  שמו״ר פכ״ג: לא נתיישב כסאך ולא נודעת בעולמך עד שאמרו בניך שירה.\nנִתְיַשֵּׁב נתפ׳, 5 נחה דעתו to come to  עיר׳ ס״ה ע״א: כל המתיישב ביינו.</p>","notation":[]},"39298":{"h":"יְשֵׁבָב","r":"KRU08886","alt":[],"source":"krupnik","glosses":[{"text":"name of a Tannai","label":""}],"html":"<p>שם תנא name of a Tannai  חול׳ פ״ב מ״ד: רבי ישבב אומר נבילה רבי עקיבא אומר טריפה.</p>","notation":[]},"39299":{"h":"יֵשׁוּ","r":"KRU08888","alt":[],"source":"krupnik","glosses":[{"text":"Jesus of Nazareth","label":""}],"html":"<p>הנוצרי Jesus of Nazareth  סנה׳ מ״ג ע״א (עפ״י קונטרס השמטות הש״ס): בערב פסח תלאוהו לישו והכרוז יוצא לפניו ארבעים יום ישו יוצא ליהרג על שכישף והסית והדיח את ישראל; ע״ז י״ז ע״א (עפ״י הקונטרס הנ״ל): ומצאתי אחד מתלמידי ישו הנוצרי ויעקב איש כפר סכניא שמו.</p>","notation":[]},"39300":{"h":"יִשּׁוּב","r":"KRU08889","alt":[],"source":"krupnik","glosses":[{"text":"inhabited land","label":"1"},{"text":"cultivation","label":"2"},{"text":"name of a place in Palestine","label":"4"}],"html":"<p>1 ארץ נושבת, מקום מושב בני אדם inhabited land  שהש״ר ח׳ א׳: המדבר שהוא חוץ לישוב.\n2 תקון הארץ, תרבות cultivation  ב״מ ק״א ע״א: אמר הלה זיתיי אני נוטל אין שומעין לו מ״ט משום ישוב ארץ ישראל.\n3 עי׳ יִשּׁוּב הַדַּעַת. אבות פ״ו מ״ה: והתורה נקנית וכו׳ בלימוד בשמיעת האוזן וכו׳ בישוב. \n4 שם מקום בא״י name of a place in Palestine  תוס׳ דמאי א׳ י״א: כיפת הישוב וכו׳ בראשונה היו דמאי מפני שחזקתן מהר המלך.</p>","notation":["ז׳"]},"39301":{"h":"יִשּׁוּב הַדַּעַת","r":"KRU08890","alt":[],"source":"krupnik","glosses":[{"text":"calmness","label":""}],"html":"<p>דעה צלולה, מנוחת הנפש calmness  ב״ר פ״כ: בישוב הדעת באת עליו אמרה לו מה את סבור וכו׳.</p>","notation":[]},"39302":{"h":"יָשׁוּב","r":"KRU08891","alt":[],"source":"krupnik","glosses":[{"text":"cutivated","label":""}],"html":"<p>מתוקן cutivated  ב״ב פ״ד מ״ט: לא מכר לו וכו׳ ולא את הגת ולא את השובך בין חרבין בין ישובין.</p>","notation":["ת׳"]},"39303":{"h":"יִשּׁוּן","r":"KRU08892","alt":[],"source":"krupnik","glosses":[{"text":"leaving unused","label":""}],"html":"<p>הנחת כלים בלי שמוש leaving unused  תוס׳ ע״ז ח׳ ג׳: העקלין של נצרין וכו׳ צריך לישן וכמה ישונן שנים עשר חודש.</p>","notation":["ז׳"]},"39304":{"h":"יְשׁוּעַ הַבֵּן","r":"KRU08893","alt":[],"source":"krupnik","glosses":[{"text":"the redemption of the first-born son","label":""}],"html":"<p>פדיון הבן הבכור the redemption of the first-born son  ב״ב ס׳ ע״ב: שפשטה מלכות שגוזרת עלינו וכו׳ ואין מנחת אותנו ליכנס לשבוע הבן ואמרי לה לישוע הבן.</p>","notation":[]},"39305":{"h":"ישט","r":"KRU08894","alt":[],"source":"krupnik","glosses":[{"text":"to hand","label":"אוֹשֵׁט אפ׳, אתפ׳, 1"},{"text":"to recite","label":"אוֹשֵׁט אפ׳, אתפ׳, 2"},{"text":"to be stretched forth","label":"אִתּוֹשַׁט אתפ׳"}],"html":"<p>אוֹשֵׁט אפ׳, אתפ׳, 1 הושיט, פשט ידו לתת to hand  תרג׳ מש׳ ל״א כ׳ (כפה) פרשה לעני): ודרעה אושיטה לעליבי.\nאוֹשֵׁט אפ׳, אתפ׳, 2 הרצה to recite  ירוש׳ מגי׳ פ״ד ע״ד ע״ד: חמא חד ספר מושט תרגומא מן גו ספרא.\nאִתּוֹשַׁט אתפ׳ הושט to be stretched forth  תרג׳ יב״ע בר׳ ט״ז י״ב: יתושטון לאבאשא ליה.</p>","notation":["Source marks no qal form"]},"39306":{"h":"יְשִׁיבָה","r":"KRU08895","alt":[],"source":"krupnik","glosses":[{"text":"sitting","label":""},{"text":"dwelling","label":""},{"text":"academy","label":""},{"text":"living in large cities","label":""}],"html":"<p>1) פעולת היושב sitting  כת׳ ק״א ע״א: אל תרבה בישיבה שישיבה קשה לתחתוניות ואל תרבה בעמידה שעמידה קשה ללב. 2) התגוררות dwelling  ספרי דב׳ פ׳: ישיבת ארץ ישראל שקולה כנגד כל המצות שבתורה. 3) בית מדרש academy  זבח׳ פ״א מ״ג: ביום שהושיבו ר׳ אלעזר בן עזריה בישיבה. יְשִׁיבַת כְּרַכִּים התגוררות בערים גדולות living in large cities  כת׳ ק״י ע״ב: ישיבת כרכים קשה. </p>","notation":["נ׳"]},"39307":{"h":"יְשִׁיוִין","r":"KRU08896","alt":[],"source":"krupnik","glosses":[{"text":"ballast-stones","label":""}],"html":"<p>ר, אבני מעמסה לשווי המשקל בספינה ballast-stones  תוס׳ צוק׳ ב״ב ד׳ א׳: המוכר את הספינה וכו׳ לא מכר לא את היצעין ולא את הישיוין.</p>","notation":["ז׳"]},"39308":{"h":"יִשֵּׁן","r":"KRU08899","alt":[],"source":"krupnik","glosses":[{"text":"to store, to reserve","label":"פיעל, 1"},{"text":"to leave unused","label":"פיעל, 2"},{"text":"to be stored up","label":"נִתְיַשֵּׁן נתפ׳,"}],"html":"<p>פיעל, 1 שם למשמרת to store, to reserve  דב״ר פ״ט: מן היין הזה אני מיישן לשמחתו של בני.\nפיעל, 2 הניח בלי שמוש to leave unused  ירוש׳ ע״ז פ״ה מ״ה ע״ג: מיישנן כל שנים עשר חודש.\nנִתְיַשֵּׁן נתפ׳, נשתמר זמן רב to be stored up  ספרי דב׳ מ״ח: ומה יין אתה טועם טעם יין מתחילתו וכל זמן שהוא מתיישן בקנקן סופו להשביח אף דברי תורה וכו׳.</p>","notation":[]},"39309":{"h":"ישף","r":"KRU08901","alt":[],"source":"krupnik","glosses":[{"text":"to kindle","label":"אוֹשַׁף אפ׳,"}],"html":"<p>אוֹשַׁף אפ׳, הדליק to kindle  שבת קי״ט ע״א: מושיף נורא.</p>","notation":["Source marks no qal form"]},"39310":{"h":"יִשְׂרָאֵל","r":"KRU08903","alt":[],"source":"krupnik","glosses":[{"text":"a Jew","label":""}],"html":"<p>יהודי a Jew  ב״ב נ״ה ע״א: ישראל שלקח שדה מנכרים ובא ישראל אחר והחזיק בה.</p>","notation":["Marked biblical in source"]},"39311":{"h":"יַשְׁרוּת","r":"KRU08904","alt":[],"source":"krupnik","glosses":[{"text":"righteousness","label":""}],"html":"<p>יושר וצדק righteousness  ספרי דב׳ ש״ז: צדיק וישר הוא שהוא מתנהג בישרות עם כל באי העולם.</p>","notation":["נ׳"]}};
